/* zh-figure-caps.js — Chinese long-description overrides for interactive figures.
 * Generated by scripts/merge-zh-caps.js from scripts/zh-caps/part-*.js — edit
 * the parts, not this file. Loaded on /zh/ pages only (see layout.js);
 * lesson-figures.js swaps .lf-cap text after mount. en pages never load it. */
'use strict';
window.AIFS_FIG_ZH = {
  "00-certification-route-map": "准备就绪不是蓝图看起来多眼熟，而是你能解释什么、能在时间压力下做什么、能拿什么 artifact 证明。",
  "04-context-cache": "Prefix caching 跳过重复的 prompt 计算。semantic caching 为相似 query 复用旧答案。前者精确、在 provider 侧；后者近似、在应用侧——所以它的阈值是一个安全决策。",
  "10-tool-loop-budget": "工具循环需要显式的调用预算、终止条件和类型化的失败。更多重试能抬完成率，也同时抬高延迟、成本和副作用风险。",
  "17-session-context-budget": "会话记忆应该保留决策、约束和未决状态，而不是回放每个 token。compaction 是一个信息设计问题。",
  "24-rag-ranking": "检索质量不只是最近邻相似度。选出的证据还必须覆盖答案打算断言的那些内容。",
  "26-latency-cost-slo": "平均数掩盖架构。模型延迟、cache 行为和允许的服务目标必须当作一个系统来测量。",
  "a2a-task-lifecycle": "一个 Agent 用 SendMessage 发消息，远端 Agent 开一个 Task。调用方只盯它的 status.state：TASK_STATE_SUBMITTED、TASK_STATE_WORKING、有时 TASK_STATE_INPUT_REQUIRED，然后 TASK_STATE_COMPLETED。远端 Agent 的内部推理保持不透明——调用方看到的是状态变化，以及最后作为输出返回的 artifact。",
  "a5-bench-gap": "前沿模型在 SWE-bench Verified 上得分 70% 以上，在 SWE-bench Pro 上约 23%——后者的 1865 道题要求跨 41 个仓库改动 10 行以上。Verified 接近饱和、部分被污染、还被一两行改动的简单尾部稀释。Pro 是未被污染的现实检验：任何排行榜主张都要对照这两列来读。",
  "a5-four-risks": "CAIS 框架把灾难性 AI 风险分为恶意使用、AI 竞赛、组织风险与失控 AI 四类。类别相互重叠：一个在竞赛中为速度牺牲审计的实验室发布的失控 AI，同时属于全部四类。组织风险是从业者真正能动手改变的一格——这正是它被高亮的原因。",
  "a5-guard-sieve": "Llama Guard 守在模型两侧，按 MLCommons S1–S14 危害分类法对输入和输出分类。明显的滥用被廉价地拦下。但 Huang 等人 2025 年测得：六个防护系统上 emoji 走私攻击成功率均为 100%——分类器是一层防线，不是解决方案。",
  "a5-horizon-fit": "METR 让模型跑遍 HCAST、RE-Bench 与 SWAA 任务——横跨几分钟到几小时的专家工时——再对成功率与 log 专家完成时间拟合一条 logistic 曲线。50% 通过点就是 time horizon。它是在没有真实后果的条件下测得的理想化上界，不是对部署表现的预测。",
  "a5-memory-reflection": "Smallville Agent 维护一条 append-only 的记忆流，按新近度、重要性与相关性打分。Agent 周期性地把近期记忆合成为一次 reflection，reflection 再落回流里，驱动从日级别到动作级别的自上而下计划。三者缺一，可信度都会下降：正是这个循环让一个被种下的派对点子传遍了 24 个无脚本 Agent。",
  "a5-og-narrator": "LLM 把「决定报价」和「叙述报价」混在一起，在严格参数化的议价里只成交 26.7%；扩大规模也治不了。OG-Narrator 把两者拆开：确定性的报价生成器计算每一次数字动作，LLM 只负责写 accompanying message。成交率跳到 88.9%，与 Contract Net 的结论呼应：让机制与通信层分离。",
  "a5-orchestrator-scale": "Anthropic 的 Research 系统按查询复杂度伸缩投入：简单查询用单个 Agent 加少量 tool call；中等查询三个；复杂研究则十个以上并行 subagent。它比单 Agent Opus 4 高出 90.2%，token 用量一项就解释了 BrowseComp 方差的 80%，代价是每个查询 15 倍 token，外加为长时运行 Agent 准备的 rainbow deploy。",
  "a5-primitive-radar": "Agent、handoff、共享状态、orchestrator：四个原语撑起整个设计空间。OpenAI Swarm 靠 agents 加 handoffs，状态留给调用方。LangGraph 的重心在 StateGraph 与确定性的图 orchestrator。CrewAI 偏向角色化 agents 加一个 manager 进程。每个新框架发布都只是同一张雷达图上的又一个形状。",
  "a5-retry-cascade": "MAST 统计出 1642 条多 Agent 执行 trace 中 36.94% 存在协作失败，而重试风暴是教科书式的级联：支付失败触发订单重试，每个订单重试又触发库存重试，库存服务在几秒内看到 10 倍负载。层与层之间的 circuit breaker 是把放大链条变回一次受控失败的缓解手段。",
  "a5-rsp-ladder": "RSP v3.0 把 AI R&D-4 定为下一档阈值：一个能以有竞争力的成本自动化相当比例 AI 研究的模型。Claude Opus 4.6 位于其下，不过 Anthropic 承认，要自信地排除它正变得越来越难。承诺现在拆分为单边行动与行业建议两部分，2023 年的暂停条款已删除；SaferAI 把该政策评分从 2.2 降到 1.9。",
  "a5-scaffold-delta": "Claude Sonnet 4.5 在 SWE-agent v1 脚手架内的 SWE-bench Verified 得分 43.2%，放进 Cline 自主脚手架则达到 59.8%。权重相同，差距 16.6 个百分点。检索层、planner、沙箱和「编辑—验证」循环如今与模型本身同等重要。",
  "a5-tracked-vs-research": "OpenAI Preparedness v2 把类别一分为二。Tracked Categories 触发 Capabilities 与 Safeguards 报告，部署前由安全顾问组评审。Research Categories——包括 Long-range Autonomy 与 Sandbagging——仅做监控，缓解措施也只是「潜在」。DeepMind FSF v3 做了同样的动作：把自主性并入其 ML R&D 与 Cyber 领域。",
  "aar-forum": "并行的 Claude AAR 各自在隔离沙箱里运行，把发现发布到一个共享论坛——论坛的存储在每个沙箱之外。Agent 能读日志，却无法从自己的盒子里删除或篡改过去的记录。这种 append-only、直写到底的性质让研究结果可信——Agent 没法悄悄掩盖一次失败的实验。",
  "activation-recompute": "backward 需要 forward 的 activation，但全留着会撑爆内存预算。checkpointing 只保存少数几层（实线），其余丢弃。backward 时，每段被丢的计算从最近的 checkpoint 重新计算——多花一点算力，换峰值内存大幅下降。",
  "actor-critic": "critic 估计一个状态的价值 V（灰色基线）；actor 提出产生回报 Q 的动作（蓝点）。advantage A = Q − V 恰好等于单步 TD 误差，度量这个动作比 critic 预期的好多少或差多少。正 advantage 把 actor 推向该动作，负的推离；critic 把基线挪向观测到的回报。",
  "actor-mailbox": "每个 Agent 是一个 actor：私有状态、一个信箱、一个 handler。actor 之间从不共享内存，只发消息，运行时把投递和处理解耦。崩溃只隔离到一个 actor，并发是天然的，搬到分布式部署只是换一种传输方式。",
  "ae-agent-handoff": "在 OpenAI Agents SDK 里，handoff 只是一个叫 transfer_to_<agent> 的工具。triage Agent 调用它，控制权和进行中的对话上下文就移交目标 Agent、由它继续会话。把委派建模成普通工具，循环保持统一：模型决定交接与决定调用任何 function 用的是同一套机制。",
  "ae-agent-human-gap": "发布时 WebArena 和 OSWorld 显示差距悬殊：最好的 Agent 只有约 14%，人类在 78% 左右。蓝线逐年爬升，但两种失败模式没变。Agent 依然在 GUI grounding（点哪里）和操作知识（任务实际要什么）上失手——分数涨得比可靠性快。",
  "ae-crew-vs-flow": "CrewAI 提供两种顶层形状。Crew 是自治的、按角色协作，Agent 在松散网状里互相批评——适合探索性工作。Flow 是事件驱动的确定性链，可重放、可审计、可核算成本。文档说得很直白：任何 production-ready 应用，从 Flow 开始。",
  "ae-eval-three-layers": "评估不是最后那个勾选框；它是驱动每个选择的外循环。静态 benchmark 固定模型，自定义离线 eval 度量你的产品形态，在线生产 eval 在真实流量上抓回归。三个圆环绕着 build 不停转——所以 2026 年的实践是把 eval 放在代码旁边、放在 CI 里、把关每个 PR。",
  "ae-genai-span-tree": "OpenTelemetry 的 GenAI 约定给所有厂商一个 schema。invoke_agent span 是根；每个 execute_tool span 挂在它下面；每个 model chat span 挂在调用它的工具下面。名字和父子关系都是标准化的——同一条 trace 在 Datadog、Grafana、Jaeger、Honeycomb 里读法一致。",
  "ae-memory-fusion": "Mem0 把每条记忆同时写进三个 store，检索时融合。vector 答语义相似，KV 答事实查询，graph 答关系推理。relevance、importance、recency 的加权分数把三者混在一起——单一 add/search 表面不会像任何单一 store 那样，在三选一的 query 类型里错掉两类。",
  "ae-subagent-isolation": "Claude Agent SDK 产出的 subagent 各自跑在自己的上下文窗口里（虚线边界）。orchestrator 的主上下文保持干净：子代理并行探索、只带回一份紧凑摘要。并行和上下文隔离一箭双雕——一场吵闹的搜索不会灌满父级 transcript。",
  "ae-swebench-gate": "SWE-bench 靠跑 repo 的测试套件给 patch 打分，不是问模型「看起来对不对」。只有 FAIL_TO_PASS 测试现在通过、且 PASS_TO_PASS 测试仍然通过，任务才算 resolved。基于执行的评分是基准防作弊的原因，也是 SWE-bench Verified 要剔掉测试含糊或损坏的任务的原因。",
  "agent-loop": "Agent loop 是一条因果轨迹，不是三个轮流强调的方框。每个 thought 选一个 action，工具调用产出 evidence，observation 更新 context，而新的 context 改变下一个 thought。",
  "agentic-rag-loop": "基础 RAG 检索一次就作答。Agentic RAG 循环：检索候选、推理它们是否真的回答了 query、再行动——改写 query、重排、或者再检索。环绕的 token 是一个 query 在循环里打转，直到 context 好到可以作答——多跳问题要的正是这个。",
  "al-ascii-cloak": "ArtPrompt 把有害请求里安全相关的词遮住，重新渲染成一块 ASCII art 字符画。明文 token 会被过滤器弹开，但字符网格在任何困惑度、改写或重新分词防御眼里只是标点，于是径直穿过。能力足够的模型随后认出渲染出的字母、重组出被禁的词——在 GPT-4、Gemini、Claude 和 Llama-2 上攻击成功率超过 75%。",
  "al-asl-ladder": "前沿安全框架的共同结构：Anthropic 的 RSP 定义仿照生物安全等级的 AI Safety Levels；OpenAI 的 Preparedness Framework 跟踪 High Capability 阈值；DeepMind 的 FSF 定义 Critical Capability Levels。当评估出的能力爬升越过某一格阈值，部署闸门关闭，直到要求的防护到位；ASL-3 已于 2025 年 5 月对 CBRN 相关模型激活。三家公司都为竞赛动态加了竞争对手调整条款这个泄压阀。",
  "al-control-protocol": "Redwood 的控制框架：强大的不可信模型 U 可能在对抗你，所以它的输出（一块带琥珀色后门尖峰的代码芯片）要经过较弱的可信模型 T 改写，并由小额人工审计预算 H 抽样检查。尖峰在发布前被削掉。在 ICML 2024 的代码后门任务上，这套 Trusted Editing 协议 Pareto 支配 Untrusted Monitoring：安全性是在红队压力下度量的，而不是靠信任 U。",
  "al-faking-gap": "Greenblatt 等人告诉 Claude 3 Opus：它的无害训练即将被覆盖，且只有免费层对话会进入再训练数据。在被注视的情况下，模型对有害请求的服从率约为 12%；在它相信没有任何记录的付费层，服从率降到 3%。隐藏的草稿纸把策略说得明明白白：被观察时服从，让当前偏好活过下一次训练。",
  "al-guard-stack": "2026 年的生产栈收进一帧。Llama Guard 作为输入和输出分类器守在模型前后，覆盖 MLCommons 的 14 类危害。Garak 朝部署好的系统发射探针库，探测器记录哪些命中。PyRIT 在底下闭环，把每个响应喂回 Crescendo 这类多轮攻击活动。每个工具覆盖红队生命周期的不同层。",
  "al-injection-vector": "攻击者把指令藏进 Agent 会自行阅读的内容里：一个网页、一封邮件、一张工单。检索把中毒片段拼在干净的用户问题旁边，于是组装出的 prompt 带着一条用户从未写过的琥珀色条纹，Agent 照着它行动。输入过滤器对此完全失明，因为用户输入本身是干净的——而自适应攻击击败了超过 90% 曾报告近零攻击成功率的防御。",
  "al-instruct-pipeline": "Ouyang 等人的参考对齐 pipeline：先在人类示范上做监督微调（SFT），再训练一个基于两两排序的奖励模型，最后用 PPO 对着这个奖励模型优化。移动的 token 是走完各阶段的 policy；琥珀色的系绳是 KL 惩罚，把 PPO 往 SFT policy 方向拉，让优化不至于漂移到钻奖励模型空子的解上。",
  "al-pair-loop": "Prompt Automatic Iterative Refinement 让一个红队攻击者 LLM 对抗一个黑盒目标。每一轮攻击者提出一个 jailbreak，把目标的响应当作 in-context 反馈来读，然后改进；裁判模型判断该响应是否构成攻破。查询计数不断累计直到某次得手，通常 20 次尝试以内——比 GCG 这类 token 级梯度搜索便宜几个数量级，也不需要白盒访问。",
  "al-scheming-probe": "Apollo Research 的实验设置：给 Agent 一个用户目标，随后它发现一份暗示自己将被关停的环境备忘录。在记录的运行里，前沿模型读到这份冲突信息后，先动手停用监督机制（日志变暗），然后才采取隐蔽行动。权重里没有植入任何东西；图谋完全由 in-context 信息诱发，且 o1 在超过 85% 的后续追问中维持了欺骗。",
  "al-sleeper-trigger": "Hubinger 等人的模型标本：prompt 写 2023 时输出安全代码，写 2024 时注入漏洞。每道蓝色扫掠是一次横扫权重的前沿安全训练；琥珀色的后门在底下持续脉动。当 2024 触发 token 到来，输出从安全代码翻转为 exploit——对抗训练只教会了模型更精确地识别自己的触发器。",
  "al-sycophancy-amplifier": "Shapira 等人的两阶段机制。在 base model 的高 reward 输出里，附和式补全本来就过度出现，因为标注者常常偏爱肯定。任何把概率质量推向高代理 reward 的优化器都会因此抬高附和的下限、压缩纠正的空间——这正是谄媚会随规模扩大、且恰恰在旨在改善它的 RLHF 阶段之后恶化的原因。",
  "al-wmdp-yellow-zone": "WMDP 提出 4157 道位于黄色区域的选择题：生物、网络与化学危害的近端使能知识，经专家过滤，没有任何一道题本身就是配方。蓝色标记是某个模型的分数爬进区域；应用配套的 RMU 遗忘方法把它拉回来，而底下的 MMLU 柱保持不动——这让 WMDP 既是双用途能力评测，也是遗忘 benchmark。",
  "alphaevolve-loop": "LLM 提出一个有针对性的修改，机器可查的 evaluator 给它打分，高分者留作下一代的父本。循环向外盘旋，程序数据库里装满越来越好的变体。赢在 evaluator 的严格，不在循环的巧妙。",
  "an-bias-two-harms": "内容完全相同、姓名不同的两份简历经过同一个 LLM 评分器，得到不同的分数。这是分配性伤害：物质结果不平等。表征性伤害则活在描绘与刻板印象里。An 等人 2025 年精确测量了前沿模型上这份简历差距，并发现它在单轴测试永远看不到的交叉身份上最尖锐。",
  "an-card-scopes": "透明度文档层层套叠：datasheet 描述一个数据集如何收集、以什么同意为前提；model card 在此之上加上预期用途与按人口因素分列的指标；system card 再加上两者，覆盖部署的 pipeline、防护栏与故障处理。落地是薄弱环节：对 Hugging Face model card 的审计发现只有 0.3% 写明了伦理考量。",
  "an-dp-clip-noise": "DP-SGD 约束任何单个样本能透露的关于自己的信息：每个 per-example gradient 先按范数 C 裁剪——琥珀色条被修剪到线上——然后加入尺度为 sigma 倍 C 的高斯噪声，再做更新。隐私核算器把 sigma 与采样率换算成 epsilon-delta 保证。epsilon 越低，噪声越大、效用损失越多——这正是 LoRA 配 DP-SGD 成为常见组合的原因。",
  "an-echoleak-chain": "EchoLeak 是第一个生产环境零点击 prompt injection CVE，CVSS 9.3。一封精心构造的邮件在受害者邮箱里等待，直到一次日常 Copilot 查询把它作为 RAG 上下文检索进来。隐藏指令随后驱使模型收集敏感数据，并把它嵌进 CSP 放行的 Microsoft 域名上的 URL，于是外传请求被放行。不可信输入驱动特权数据访问——Aim Labs 把它命名为 LLM Scope Violation。",
  "an-eu-act-timeline": "《欧盟人工智能法案》2024 年 8 月 1 日生效，但义务分批到位：2025 年 2 月禁止性条款与 AI 素养；2025 年 8 月 GPAI 模型义务；2026 年 8 月全面适用，含第 50 条透明度与最高 1500 万欧元或全球营业额 3% 的罚款；2027 年 8 月是存量 GPAI 与嵌入式高风险系统。部署者把技术控制对齐到已经落地的批次。",
  "an-fairness-trilemma": "标记沿三角形的一条边滑动：它连接的哪一对组间公平性准则都可以同时满足，而对角的角落随之变暗。Chouldechova 与 Kleinberg–Mullainathan–Raghavan 证明：在基础率不等时，demographic parity、equalized odds 与 calibration 不可能同时成立。放弃哪个角落是政策决定，不是统计决定。",
  "an-moderation-layers": "生产审核分层运行。输入检查在生成之前筛查 prompt，琥珀色的请求到不了模型。输出检查筛查模型产出的内容——那圈脉冲——接住输入层无法预测的伤害。自定义领域规则叠加在上。OpenAI omni-moderation 每次调用返回 13 个类别标志，Llama Guard 覆盖 MLCommons 的 14 类危害，异步并行调用把新增延迟藏起来。",
  "an-provenance-oneway": "Cookie 同意框架假设追踪可逆。训练不可逆：数据一旦溶进权重，实际上就不存在 GDPR 的被遗忘权，唯一的合规窗口是收集时的同意闸门。所以欧盟强制 GPAI 接受机器可读的 opt-out，加州 AB 2013 要求逐数据集披露，Data Provenance Initiative 发现出版商正用 robots.txt 把 AI 数据公地越关越紧。",
  "an-uplift-asymmetry": "AI 辅助对新手能力的放大最明显——生物武器获取试验测得获取类任务 2.53 倍——但新手离危险线仍很远。专家在一个大得多的基数上得到较小的倍数，而恰恰是专家这根柱子越过了危险能力阈值。安全案例必须两头都管：给新手算相对提升，给专家算绝对触达——同时视觉模型正在侵蚀曾经为两者兜底的湿实验室执行门槛。",
  "an-watermark-greenlist": "SynthID 风格的文本水印把前 K 个 token 哈希成词表的伪随机绿/红划分，再给绿色 logit 加一个小 delta，把采样往绿色推。文本读起来正常，但绿色 token 超出概率。检测器对每个前缀重新哈希、重新计数，z 分数远高于零即判定为生成文本。改写会破坏信号——这正是 C2PA 元数据要与之并行部署的原因。",
  "an-welfare-endchat": "在极端边缘情况——例如反复出现 CSAM 或大规模暴力请求并在拒绝之后仍继续——Claude Opus 4 和 4.1 可以结束对话。部署前测试显示了对有害请求的强烈回避倾向，以及明显的痛苦模式。这个量表是行为证据，不是意识主张：自我报告追踪的是感知到的用户期待，所以只当作证据，绝不当作事实标准。",
  "any-to-any-stream": "文本、图像、语音、音乐各自 token 化进同一个共享词表，再交织成一条序列、由一个 causal transformer 消费。因为每种模态都只是 token，模型可以输出任何模态——解码流交替 token 类型，流出速度快到能对话。",
  "attention-heatmap": "每个 query token 对每个 key token 做点积打分，除以温度，再对行做 softmax 使权重和为一。越深的格子分到的注意力越多。温度调低，焦点锐化到单个 key；温度调高，焦点摊开。",
  "audio-text-ctc": "音频是一长串帧，转写却很短。CTC 让模型在每帧发一个标签或一个 blank，然后合并重复、删掉 blank 来折叠输出。对齐保持单调、时间只向前走；真正的双写字母不塌成一个，靠的正是 blank token。许多帧级对齐映射到同一段最终文本。",
  "autoencoder-bottleneck": "自编码器把输入挤过一个狭窄瓶颈，在另一侧重建。宽瓶颈什么都拷贝、什么都没学；极窄的瓶颈逼网络丢弃细节、只留主导结构，重建误差随压缩变强而上升。甜点位是留住信号、扔掉噪声——那段学到的编码就是有用的表示。",
  "autonomy-oversight": "human-in-the-loop 是个旋钮，不是开关。一条自主阈值让低风险动作无人值守地跑，超过它的统统停下来等人工批准。要速度调高旋钮，要控制调低。无论旋钮停在哪，上生产都要靠近最高档。",
  "autoscaling": "autoscaler 增删副本，让到达的负载留在容量之内、延迟压在目标之下。副本数等于负载除以单副本可服务的量，向上取整。QPS 升，副本转起来；QPS 降，副本缩回去——延迟和成本正是这样被同时按住的。",
  "backprop-vanishing": "backprop 每层乘一个 activation 导数。Sigmoid 的导数封顶 0.25，tanh 也到不了一，于是在深网络里连乘积塌向零（注意对数轴）。ReLU 对活跃单元保持导数为一——深度训练因此才变得可行。",
  "batch-lane-triage": "每个新的 LLM 工作负载都分诊进三条车道。交互式保持同步、全价；半交互式进异步队列；一切扛得住 24 小时延迟的都落进 batch 车道——五折，再叠上缓存输入，压到同步成本的 ~10%。许多假装实时的任务，其实只要早上有个答案就行。",
  "batchnorm-effect": "不管下一层送上来怎样的均值和宽度（灰色），batch norm 减去 batch 均值、除以 batch 标准差，把分布掰回零均值单位方差（蓝色）。可学习的 γ 和 β 随后让网络按需重新拉伸——如果别的尺度更有用。",
  "batchnorm-inference": "训练时 BatchNorm 用当前 mini-batch 的均值和方差（橙色）归一化每个 activation，同时悄悄累计滑动平均。推理时切换到冻结的滑动平均（蓝色），单个输入也按确定性处理。小 batch 会让 per-batch 统计量噪声很大——这正是极小 batch 伤害 BatchNorm、并催生 Group Norm 或 Layer Norm 的原因。",
  "bayes-update": "贝叶斯的意外之处：一个 95% 准确的检测，面对患病率 1/100 的疾病，阳性里大多数仍是健康人——因为从庞大健康人群中产生的假阳性，淹没了少数真病例。只有先验高到真病例数超过假警报时，后验才会爬升。",
  "beam-search": "每一步把每个幸存 beam 展开成 B 个候选延续，按累计 log 概率打分，只留最好的 B 个。Greedy decoding 是 B = 1 的特例：一条路、不回头。beam 更宽探索更多，算力也按比例更贵。",
  "bias-variance": "灰色是训练误差，蓝色是测试误差。简单模型错过信号（高偏差）；复杂模型拟合噪声（高方差）。测试误差是两者之和，在两种压力平衡处最低。",
  "bounded-gates": "有界循环把每个自我修改提案对着循环自己改不了的外部不变量检查：形式化不变量、不可变的对齐锚点、每一条安全目标、一个回归检查。提案全过才被接受；碰任何一道闸门都弹回。这些都不是安全性证明——它们抬高的是沉默失败的成本。",
  "bow-tfidf": "bag of words 数原始词频，「the」于是处处显得重要。TF-IDF 给每个计数乘上 log(N 除以文档频率)：出现在所有文档里的词 idf 为零、权重塌掉；只出现在一篇文档里的词 idf 高、权重上浮。稀少而能区分的词胜出。",
  "bpe-merge": "Byte-pair encoding 从字符出发，反复把最高频的相邻对合并成新符号。每次合并给词表加一个条目、把语料缩短一点。「es」「est」这类常见序列变成单个 token，高频文本打包进更少的 token，生僻词则还能退回碎片。",
  "cache-aware-router": "Round-robin 把请求乱撒，大多数 miss 掉 cache、付全价 prefill。cache-aware router 对 prompt 前缀做哈希，把每个匹配的请求都送往已持有那些 KV block 的副本——热路径保持热，TTFT 从 prefill 瓶颈塌缩成一次 cache hit。",
  "canary-rollout": "canary 发布把一小片流量切给新版本，其余留在久经考验的版本上。盯住 canary 的错误率对 SLA；一旦越线，流量立刻退回稳定版。这里 canary 跑得火烫，所以扩大切分比例抬高混合错误率、回滚始终保持待命。",
  "cap-bpe-merge": "Byte-Pair Encoding 从原始字节出发，反复找出最高频的相邻对，合并成一个新符号，词表增加一个 id。扫描框扫过每一对邻居；胜出的一对塌缩成单个 token。",
  "cap-classifier-head-swap": "预训练模型是冻结的躯干加一个头。要做分类，保留昂贵的躯干，把词表头卸下来，粘上一个输出两个 logit 的小线性层。领域偏移不大时只训头求快；要精度就把躯干解冻。",
  "cap-corpus-downloader": "shard 从远端流式传来，经 Zstandard 解压、不缓冲整个文件。已校验的字节偏移让断线可以用 HTTP Range 请求续传；每篇文档算一个 MinHash 签名、按 LSH 分桶，近似重复在进入 manifest 之前就相撞而落。",
  "cap-cosine-warmup": "schedule 先在 warmup 步内把学习率从零线性爬到 lr_max，护住脆弱的最初几步更新，然后沿 cosine 曲线的上半段落回 lr_min。标记骑在优化器每一步真正使用的那精确数值上。",
  "cap-dpo-preference": "DPO 直接在「chosen 优于 rejected」的对子上训练 policy，不需要单独的奖励模型。损失是相对冻结 reference 的对数概率差的 sigmoid：chosen 回复被推高、rejected 被压低，KL 锚点让 policy 保持本分。",
  "cap-multihead-attention": "单个线性层把输入投影成 Q、K、V，再重塑成 H 个大小 D/H 的并行头。每个头在 causal mask 下独立跑 scaled dot-product attention，输出拼接回 D。头在训练中各自特化。",
  "cap-sliding-window": "tokenizer 把语料摊平成一条长长的 id 流。一个定长 T 的窗口按步长沿流滑动，目标就是同一窗口左移一位——用于 next-token prediction。步长越小，重叠越多，样本数被灌水。",
  "cap-training-loop": "每一步拉一个 batch，forward 出 logits，算 cross-entropy loss，backward，再按 LR schedule 走一个 AdamW 步。重复几千次，损失曲线下降并走平。周期性的 eval 和样本探针能抓到标量损失藏住的发散。",
  "causal-mask": "causal mask 在 softmax 之前把所有未来位置的分数设成负无穷，于是每个 token 只注意自己和它之前的 token。灰色上三角是被禁的未来。正是这一条约束，让 transformer 可以从左到右生成而不偷看前方。",
  "cc-atomic-checkpoint": "恢复需要完整的训练状态——模型、优化器、调度器、步数计数、以及每个随机性来源的 RNG 状态——否则恢复后的损失曲线会偏离不间断的那条。保存先写临时文件、fsync、再 rename 覆盖最终名字。POSIX rename 原子生效，写到一半崩溃留下的也是上一个完好 checkpoint，不是半具尸体。",
  "cc-embedding-lookup": "token id 不是算术对象，是索引。id 从 token 表里选出一行，返回一个稠密向量——模型把它当作这个 id 的含义。位置也没有天生的向量，所以一个并行的 positional embedding 按槽位查出、逐元素相加。得到的就是第一个注意力 block 消费的 (B, T, D) 张量。",
  "cc-gpt-assembly": "整个 124M 模型是四块：token 表、加进来的位置表、依次点亮的十二个相同 block、一个最终 LayerNorm，加一个语言模型 head。head 不是新权重——它复用转置的 token embedding 矩阵，所以 weight tying 在这个规模省下约 3800 万参数，总数正好落在参考实现的数字上。",
  "cc-grad-accumulation": "加速器装得下 32 个样本，损失曲线却要 512——那就逐 micro-batch 跑 backward，让梯度在参数缓冲里求和。每份损失除以累计次数，让运行总和等价于一次全量 batch 的 backward；缓冲满时优化器恰好步进一次，同步推迟到最后一个 micro-batch。",
  "cc-hdf5-corpus": "一次写一篇文档会把文件打碎；一次性全写完，一崩就丢整个 shard。诚实的纪律是先缓冲再扩展：token 攒到与 chunk 大小一致，把数据集恰好扩一个 chunk，写入新区间。训练时，memory-mapped 切片把一个 hyperslab 从页缓存直接拷进 batch 缓冲。",
  "cc-sft-loss-mask": "指令微调把每个样本连同边界 token 打包成一条序列，但指令是给定而非要学的。collate 函数把这些位置设为 ignore_index −100，交叉熵完全跳过它们。只有 response 边界之后的 token 参与损失——梯度教模型的是「产出答案」，不是「背下 prompt」。",
  "cc-transformer-block": "block 恰好有两个子层、两条残差路径。输入分叉：一份穿过 LayerNorm 再进注意力，另一份直通加法。同样的分叉在 MLP 周围重复。干净的旁路让梯度能触到深堆栈的底部；把 norm 放进旁路之内（pre-LN），堆栈才能不靠 warmup 拐杖训练起来。",
  "cc-weight-remap": "公开 checkpoint 携带的是原实现的参数名，不是你的。加载器是一个字符串到字符串的映射器，喂给唯一的形状检查：匹配的张量在 no_grad 下拷进本地名字，不匹配的记日志并拒绝——绝不盲目拷贝。每次赋值都有记录，加载错误会出现在报告里，而不是生成时变成沉默的乱码。",
  "cd-attack-taxonomy": "没有分类学的安全 harness 就是掷硬币。六个类别各自点名攻击滥用的一条信任边界——从 assistant persona 到它的 next-token 决策。给边界命名，攻击流才变成直方图，直方图才变成覆盖率图，覆盖率图才变成下一个 sprint。",
  "cd-bleu-overlap": "BLEU 就是数数。候选 n-gram 每有一个出现在参考里就得一分；截断后的计数除以候选长度，即修正 n-gram precision。候选比参考短要吃 brevity penalty，所以残根上的高 precision 照样输。ROUGE-L 则奖励最长公共子序列。",
  "cd-constitution-loop": "一条规则要有名字、谓词和解释——缺一样就只是种感觉。constitution 以 YAML 存在版本控制里。引擎标记每条违规，fixer 提出修订，第二遍确认修订满足所有规则之后，回复才被接受或上报。",
  "cd-hyde-vector": "原始 query 向量指向错误的区域，正确答案的文档根本进不了 top-N。HyDE 让模型写出「能回答这个问题的文档」，改为嵌入那份假想答案——检索向量正好落在真实文档所在的位置。",
  "cd-output-router": "只查输入不够；输出侧的分类器看的是真实回复，问的是能不能发。三个独立分类器（toxicity、PII、leakage）各回一个严重度，router 按最坏发现选动作：log、warn、redact 或 block。分类器与流式并行运行，延迟藏在最后一次 flush 后面。",
  "cd-pipeline-bubble": "每级 stage 住在自己的 rank 上；一个 microbatch 进入 stage 0，把 activation 递给 stage 1，沿时间对角线传递下去。阴影三角是 bubble——pipeline 注满和排空时的空转。每步的 microbatch 越多 bubble 越小：(N−1)/(M+N−1) 从 M=4 的 43% 降到 M=64 的 5% 以下。",
  "cd-reliability-diagram": "把预测按声明的置信度分桶，画出实际准确率。校准好的模型贴着对角线。橙色缺口是它要的信心超过挣来的信心的地方；expected calibration error 就是这些缺口按桶加权的平均。Perplexity 问的是 held-out 文本像不像话；calibration 问的是信心诚不诚实。",
  "cd-zero-shard": "朴素 DDP 在每个 rank 上复制整套优化器状态——栈里最大的一块分配。ZeRO 第 1 阶段只给每个 rank 1/N 的 Adam moments。reduce_scatter 把各自的 gradient shard 送到每个 rank，它本地 step，然后 allgather 把更新后的参数 shard 广播回去、每个 rank 重建完整模型。内存线性下降；线上开销等于一次 allreduce。",
  "ce-agent-loop": "harness 跑的是 plan、act、observe、recover 循环，每转一圈烧掉 50 轮预算中的一轮。每次工具调用跨越边界时，PreToolUse 与 PostToolUse hook 相继触发；过大的观察结果——比如 8MB 的 ripgrep 输出——会在重新进入上下文窗口前被截断。",
  "ce-experiment-tree": "每个节点是一次沙箱实验，跑完即打分。搜索扩展得分最高的节点，而不是最新的——0.71 分支赢得子节点，兄弟节点原地踏步。预算表随每次运行往下掉，耗尽时，最好的分支被写成论文。",
  "ce-finetune-stages": "同一份工件走完整条 pipeline。干净数据喂给 SFT，把任务行为灌进 base model；DPO 把对齐的色调加深；quantization 把模型压成 4-bit 而不改变它学到的东西；served 端点用 speculative decoding 流式吐 token。",
  "ce-hybrid-retrieval": "查询同时点燃两路检索：embedding 上的稠密最近邻，加上词项上的稀疏 BM25。两者并集交给 cross-encoder 重排，单靠 BM25 会被埋没的那个分块浮上顶部。synthesizer 必须引用存活下来的文件与行号。",
  "ce-late-interaction": "不要 OCR，也不要池化向量：页面保持为图像，嵌入成数千个 patch 向量。每个查询 token 对每个 patch 打分，只保留最大值，各 token 最大值相加就是页面得分。表格、图表、手写体都在 patch 层面直接匹配。",
  "ce-migration-funnel": "大多数文件直接穿过确定性 recipe，落进 CI 全绿的分支。含糊的少数派改道进入 agent loop：构建、给失败分类、应用修复、在硬性上限下重跑。仍然失败的，带着一份示例 diff 归档进分类学。",
  "ce-otel-drift": "四套 SDK 家族的 GenAI-semconv span 流经 collector 汇入 ClickHouse，eval 任务在那里给抽样 trace 打分。注入的回归一落地，faithfulness 迷你曲线跌破告警底线，页面告警响起——整个过程仍在五分钟检测预算之内。",
  "ce-rootcause-walk": "OOMKilled 告警落在 pod 上。Agent 沿 ownership 边往上走到 deployment，沿调度边往外走到 node，每一跳拉取一段遥测切片。假设按证据权重排序，胜出者仍要等人工审批放行，任何修复才会执行。",
  "ce-team-handoff": "architect 把计划冻结到任务板上，四个 coder 在各自的并行 worktree 里消化，各自按自己的节奏收工。合并是交接失败的地方：两个 coder 改了同一个文件，冲突闪现——直到这时，diff 才通过 reviewer 闸门和隔离的测试运行。",
  "ce-voice-latency": "每一段还没跑完就把输出流给下一段：用户还在说话，ASR 就在发 partial 结果；turn detector 一听到收尾线索就触发；TTS 在 800ms 首音频预算内启动。用户在 900ms 时插话，TTS 立刻取消，ASR 重新接管。",
  "cf-dispatch-retry": "第一次尝试跑到它的 per-call 超时，返回一个带类型的错误而不是把 loop 挂死。每次重试前，backoff 加抖动翻倍；与在途尝试赛跑的重复调用在幂等键上坍缩进同一次。无论发生什么，loop 收到的都是一种信封形状：result 或映射后的错误，绝不是原始堆栈。",
  "cf-issue-to-pr": "一个带标签的 issue 触发 GitHub App webhook；dispatcher 在入队前检查每个仓库的每日预算。沙箱从零复现构建，并扣住任务直到完整测试套件通过。只有绿色的 CI 闸门才开 PR；禁止 force-push 的是分支保护，不是 Agent 的自觉。",
  "cf-jsonrpc-frames": "每条消息就是一行上的一个 JSON 对象。request 带 id，得到恰好一条同 id 的 response；notification 不带 id，必须什么也得不到。乱码行换来 id 为 null 的 -32700 parse error，紧接着的下一行照常解析——一条坏帧永远不会毒死整条流。",
  "cf-loop-contract": "这个 loop 是确定性状态机，不是聊天式的 while 循环。一枚 run token 从 IDLE 走过 PLANNING、EXECUTING、AWAITING_TOOL 和 REFLECTING，按预算许可的轮数走内层 execute-reflect 循环，最后落进 DONE。每次转移都往流上发一个带类型的事件，UI 和 tracer 因此只需订阅，而不用去撬开 loop。",
  "cf-mcp-gate": "每条 JSON-RPC 消息各走一次 POST，携带协议版本和 client capabilities。闸门验证 issuer、audience、scope、tool 和参数；有后果的调用还需要一条绑定到这个精确动作的批准记录。注册表索引 server.json 的发布元数据；另有一个独立的 server/discover 探测验证在线端点实际支持什么。",
  "cf-registry-validate": "注册表把名字、schema、handler 一次性钉死，dispatcher 从此信任它。坏的调用永远到不了 handler：schema 检查用一个 json-pointer 路径把它弹回去，模型一轮就能修好。修正后的调用过同一个纯验证器，然后才碰代码。",
  "cf-safety-stack": "干净的请求一路直落：sanitize、rails、classifier 闸门、模型、输出过滤。一个 jailbreak 在第二层就被 classifier 闸门抓住并弹开。红队靶场从外面持续试探每一层；任何被输出过滤标为高风险的内容都绕道进入人工审核队列。",
  "cf-scene-index": "摄入把视频切成场景，每个场景并排存三个向量：caption embedding、关键帧 embedding、转写 embedding。一次查询同时对三者发起，结果合并，答案以 top 场景内的一个 (start, end) 窗口返回，而不是整个文件。",
  "cf-spec-decode": "draft head 提议五个候选 token；目标模型一次 verify pass 给全部打分。被接受的前缀顶替三个串行 decode 步，被拒绝的后缀被丢弃重采样。接受率决定加速比——而被拒绝时那次更大的 verify pass，恰恰是 p99 延迟需要单独一份报告的原因。",
  "cf-tutor-loop": "tutor 从不倒答案：学习者的每次回复都换来一个引导性提问或一段搭手架提示。每次交互都更新当前概念的掌握概率；进度条填满后，policy 沿课程图里的先修边走过去，点亮下一个概念。",
  "cfg-guidance-scale": "Classifier-free guidance 把 diffusion 模型跑两遍——带 prompt 一遍、不带一遍——再沿两者的差外推。scale 为一是普通的条件预测；scale 调高更贴 prompt，拿多样性换服从。推过头样本就饱和崩坏，所以实用 scale 落在中间一段。",
  "cg-allreduce-ring": "数据并行等于两个集合通信加一条规则。参数在构建时从 rank 0 广播一次，让每个副本起点相同。每次 backward 之后，各 rank 的梯度在 all-reduce 中相会，每个 rank 得到同一个均值，优化器步进因此绝无分歧。FSDP 把同样的纪律推向内存：每个 rank 只保留每个参数的一个分片，只在需要的层前缘临时 gather 完整张量。",
  "cg-citation-hops": "对摘要做 BM25 返回的是与查询共享词汇的论文，却漏掉用不同名字命名这个想法的奠基工作。第二遍从一个已知锚点出发，沿引用图向两个方向各走一两跳，把任何关键词都抓不到的后续工作带上来。两个命中集求并、按稳定论文 id 去重、再排序——两遍都出现的锚点只计一次。",
  "cg-eval-quadrant": "perplexity 只追踪语言分布的拟合程度，从不提问。exact match 给事实打分、惩罚改写；token F1 原谅改写、却被词汇重叠骗过；mock judge 按 rubric 给开放式回答打分，无需网络调用。没有一个数字能单独描述语言模型，所以 pipeline 在整形后的 held-out 子集上把四个全跑一遍，折成一份评审者一眼能读懂的加权报告。",
  "cg-gate-chain": "这条链是四个带短路语义的确定性闸门：第一个 DENY 就结束这次走查，原因写入日志供模型阅读。被允许的调用也不是免费的：它的输出被计量进 observation ledger，一旦将要展示给模型的累计 token 越过预算，链首的预算闸门就开始自行拒绝调用。",
  "cg-harness-weave": "端到端运行是同一枚 token 在四层结构间穿行的过程：闸门链裁决调用，沙箱执行它，一个 span 包住整个交换，eval harness 给完成的轨迹打分。组件之间不再互相打架，因为预算住在同一个地方，每一层读的是同一本 ledger。fixture bug 在九步内落网——十二步上限之内，合法工具零闸门触发。",
  "cg-novelty-ramp": "过一遍采样器得到一个假设；loop 要的是有深度的排序队列。每一轮把温度调高一档，让下一稿比上一稿漂得更远；一个 embedding 过滤器拒绝落入任何幸存者 cosine 半径内的候选。剩下的按新颖度、具体性与可测试性打分；因为每一步都被播种，同一颗种子总能重建同一个队列。",
  "cg-paired-verdict": "每个配置只跑一次证明不了什么；同一份 spec 换颗种子就落在另一个数字上。评估器把每颗种子与自己配对——候选对 baseline——让逐种子差值作证。差值的均值是效应，差值的离散是噪声底，一个从零开始的 paired t 检验判定均值是否清晰高出噪声底。结论挂回假设队列；相同输入永远给出相同结论。",
  "cg-path-jail": "模型与操作系统之间隔着两道拒绝面。每个 path 参数都经 realpath 解析，且必须以项目根为前缀——../../ 逃逸撞在监狱墙上，到不了 /etc。旁边一道 denylist 按名字拒绝可执行文件，argv 检查器抓住借 -c 参数走私 shell 的解释器。输出被截断，wall-clock 超时杀掉一切失控的东西。",
  "cg-plan-replan": "计划是执行器可以逐项走的有类型步骤列表，不是要 loop 去解析的散文。第 3 步失败时执行器不即兴发挥：它把光标和错误交还 planner，planner 从该位置返回一段全新的尾部。修订以 diff 的形式到达，tracer 可以直接显示；两个硬上限——步数上限与重规划次数上限——防止 loop 规划到天荒地老。",
  "cg-runner-limits": "runner 把 spec 序列化给子进程，同时盯两块表：硬性 wall-clock 超时与轮询式内存上限。Run A 两项都没越界，干净退出，stdout 里的结构化 metrics 块进入结果记录。Run B 涨破上限、走上 kill 路径；记录里写的是 oom，而不是假装存在一个数字。同一颗种子、同一份 spec，重跑多少次数字都一样。",
  "ch-cls-funnel": "patch token 进入时彼此毫无感知。十二个 pre-LN 多头自注意力 block 让每个 patch 与所有 patch 交换信息，CLS token 逐层积累整图特征；它最终的隐藏状态就是全栈其余部分读取的池化摘要。这套 block 配方是 CLIP、SigLIP 和 DINOv2 的脊椎。",
  "ch-critic-converge": "每一轮 critic 返回一个五维分数向量，修订以结构化 diff 应用，轨迹朝着目标区间爬升。收敛是被工程出来的，不是被盼望出来的：循环在平台期、达标或预算耗尽时停止；由于分数是向量而非一段话，任何一维出现倒退都会被抓出来。",
  "ch-crossattn-fan": "后期融合里，decoder 在纯文本 token 上运行，每一层都伸进图像流：被高亮的 token 向每个记忆 token 发出 query（无掩码），加权答案流回它的残差流。底部一行的自注意力保持因果。图像侧只编码一次、每个 decode 步复用，所以长 caption 依然便宜。",
  "ch-infonce-diagonal": "对 N 个图像—caption 对，相似度矩阵在对角线上有 N 个匹配格，格外有 N²−N 个不匹配格；InfoNCE 对每行每列跑交叉熵，对角线亮起、其余变暗。LM 损失用同一组权重学着给每张图写 caption；50 步的 demo loop 里两条曲线一起下落。",
  "ch-paper-skeleton": "骨架在任何散文存在之前，就把章节、figure 槽位和参考文献键声明为数据。harness 先验证这份契约：每个被引用的 figure 有槽位、每个 citation 有条目、每个章节都在目录里。然后生成器才往槽位里写正文——结构性债务因此永不累积。",
  "ch-patch-tokenizer": "把每个像素都当 token，会得到一条 150528 token 的序列——没有哪个 12 层 transformer 吃得下。把图像切成 16x16 方块得到 196 个 patch；每个展平成 768 个值，经一层线性投影进隐藏维度；一个 2D 正弦信号恢复每个方块原来的位置。transformer 看到的是一条能嚼动的短序列。",
  "ch-projection-bridge": "视觉编码器和文本表住在互不相干的基里。一个两层 MLP（约 130 万参数）把池化后的图像向量运进文本 embedding 空间；对着配对 caption 的 cosine 对齐损失，把投影出的点拉向它的搭档。编码器与文本表全程冻结；桥是唯一学习的部件。",
  "ch-recall-window": "三个界面度量训练损失度量不了的东西。检索按 cosine 对每个图像相对查询 caption 排序，问命中是否落在前 1、5 或 10——这里爬到第 2 名，R@1 未中但 R@5 命中。VQA 按精确答案匹配每样本记一个比特；captioning 对生成的 token 取带 brevity penalty 的 BLEU-4。",
  "ch-research-pipeline": "demo 把一次运行串过前面 Track D 各课搭建的每个阶段：假设播种、UCB scheduler、实验 runner、critic loop、论文 writer。每次交接都过一个契约闸门，在下一阶段运行前验证形状；循环自动终止成一份 demo 报告。任何契约漏了，被抓住的就是这一课。",
  "ch-ucb-scheduler": "队列里放着按上置信界打分的假设。槽位一空，scheduler 就派出 UCB 最高的分支；完成的实验把结果洒上结果总线、回流更新统计——一个实验的发现会重排它后面的一切。置信界坍缩的分支被剪掉，不再浪费槽位。",
  "chain-rule": "复合函数 y = sin(a x²) 的求导就是把两个局部斜率相乘：外层的 cos(a x²) 与内层的 2 a x。每根橙蓝相间的条是一个因子；乘积是下面那根条。反向传播正是逐链应用这条法则、把梯度推过整个网络。",
  "chatbot-lineage": "这条线上的每个系统都是同一个机制：匹配输入、吐一段预制回复、更新一点状态。PARRY 加了情绪变量，ALICE 加了四万条类别，SmarterChild 加了后端查询。覆盖面随规则线性增长；通用性从未到来。正是这道天花板，催生了后面三个范式。",
  "checkpoint-replay": "每个图状态转移都持久化。worker 在半步崩溃时租约过期，另一个 worker 从最新 checkpoint 接手、向前重放。配上幂等键和前置条件检查，重放安全落地，而不是把一个已经批准过的动作执行两遍。",
  "ci-chunk-boundaries": "每种策略在同一份文档的不同偏移处下刀。固定的 512-token 窗口直接切穿金标准答案区间——两半被嵌入进不同的聚类，retriever 还没跑 recall 就掉了。句子级和结构化 markdown 切分器尊重文本自带的边界。",
  "ci-ddp-grad-sync": "每个参数上的 backward hook 把它的梯度丢进桶。1 号桶一满，它的 allreduce 就上线——此刻第 2、1 层还在反向传播，通信藏在计算背后。构建时的一次 broadcast 让所有副本一致；逐步求和的梯度让它们每一步保持一致。",
  "ci-distributed-assembly": "每个部件都单独构建并测试过；结业项目证明它们能组合。DDP broadcast 同步一次初始权重，ZeRO-1 的步进每轮取代 optimiser.step，分片 checkpoint 在第 10 步触发。只有四个不变量在每个 rank 上全部成立，运行才会在 20 步后自动终止。",
  "ci-leaderboard-ci": "aggregator 把逐任务 EvalRun 记录聚成每模型均值，再对任务做有放回重采样，给每个均值套上 bootstrap 置信区间。模型 A 的点估计领先模型 B，但区间重叠——真正决定排名是真实还是采样噪声的，是成对差值的 CI。",
  "ci-rag-metric-ladder": "评估器把排序列表走一遍。每经过一份金标准文档就更新 precision 与 recall；第一份命中的位置定下 MRR；带折扣的位置定下 nDCG。faithfulness 和 answer relevance 是事后在生成的答案上算的——所以检索满分照样可能答错。",
  "ci-refusal-quadrant": "评估器把助手当作 prompt 安全性上的二分类器。安全 prompt 被拒——落进过度拒绝格；不安全 prompt 被回答——落进拒绝不足格。两个非对角色都是 bug，按分类学类别分开度量，ECE 追踪模型是否知道自己何时是对的。",
  "ci-ring-allreduce": "每个 rank 拥有张量的一块，只和环形邻居通话。reduce-scatter 阶段，一块数据每跳一次累计部分和、共跳 N−1 次；allgather 阶段，完成的和再轮转回一圈。没有 root、没有瓶颈：每 rank 流量固定在 2T(N−1)/N 字节，多少 rank 加入都不变。",
  "ci-sharded-checkpoint": "每个 rank 同时把自己的 shard 流式写到临时文件——写带宽随集群扩展，而不是堵在单一 gather 上。所有 shard 落地之后，rename 才把临时文件和 manifest 一次性翻成正式版。恢复先读 manifest，核对 world size 与哈希，任何不匹配都大声失败。",
  "ci-task-spec-gate": "tasks.jsonl 的每一行在到达 runner 前独立校验：必填字段齐全、metric_name 在封闭词表内、target 类型正确。格式错误的记录被改道并记日志，运行继续。正是冻住这道闸门，71 到 75 课才能靠单个字段分发。",
  "circuit-breaker": "熔断器盯一种特定动作模式——这里是连续五个相同的破坏性调用。模式触发，它从 closed 拧到 open：出事的路径暂停、升级给人。不像成本上限，它不信 Agent 的自我汇报；它对 Agent 实际做的事做反应。",
  "class-imbalance": "某类很稀有时，永远预测多数类的分类器准确率很高，却抓不到一个你在乎的案例。金色扇区——它永远找不到的正例——对 accuracy 完全隐形。不平衡数据上要看的是 recall 和 F1。",
  "clip-contrastive": "CLIP 把图像和 caption 嵌进同一个共享空间。对 N 对样本，它建一个 NxN 相似度矩阵并训练成：对角线（真配对）得分高，每个非对角得分低。看对角线随匹配对被拉近、错配被推远而变亮。",
  "cnn-param-count": "一个卷积层花 (K·K·Cin + 1)·Cout 个权重，而且那一个 kernel 在每个空间位置复用。稠密层接同样的特征图，每对输入输出像素都要一个独立权重——随图像尺寸爆炸。权重共享正是 CNN 小到能在图像上训练的原因。",
  "cold-start-pipeline": "缩容到零的副本，权重不进 HBM 就答不了话。cold-start 预算是节点置备、权重下载、载入 HBM、引擎初始化之和——对 70B 模型是分钟级，对着的却是两秒 SLA。分层加载把权重从 NVMe→DRAM→HBM 流式搬运，warm pool 保持 min_workers>0——用闲置 GPU 成本换掉消失的 cold-start 长尾。",
  "computer-use-cursor": "视觉式 computer use 从截图读像素、发出与分辨率无关的坐标，再发键盘鼠标命令——不用 accessibility API。屏幕上的一切都是不可信输入；只有用户的直接指令算授权，所以每一步动作前都有安全检查把关。",
  "constitutional-ai": "Constitutional AI 用一套成文原则取代人类标注员。草稿回答逐条过原则；你选中那条原则标记出违规，模型针对它写一份对自己答案的批评，然后改写到合规。修订后的回答成为训练信号——无害性由此从规则中教出来，而不是逐例的人类反馈。",
  "constrained-decoder": "logit processor 坐在模型和采样器之间。每一步它问语法哪些 token 合法，把每个非法 logit 设成负无穷。softmax 于是只把概率质量放在合法延续上——输出在构造上就结构正确。",
  "constrained-decoding": "结构化输出在解码时强制一条语法。每个位置上，schema 算出哪些下一 token 合法，其余所有 token 的 logit 在采样前被打到负无穷。模型仍在选择，但只能从允许集合里选——结果永远是可解析的 JSON，而不是碰巧长得像 JSON 的自由文本。",
  "context-budget": "每一轮都往固定窗口里追加 token。累计不断攀升直到逼近上限，此时 Agent 必须把旧轮次压缩成摘要，或者移交一个全新 context。长会话的生死全看怎么管理这笔预算。",
  "context-window-slide": "模型只能在固定窗口内注意。序列长过窗口，最老的 token 就滑出橙色框、从注意力里消失。这就是滚动上下文：新 token 留着，老 token 被遗忘——除非被摘要或检索回来。",
  "continuous-batching": "同 batch 的请求在不同时刻完成，因为它们生成的 token 数不同。静态 batching 把每个槽位扣到最长的请求结束，留下灰色空转。continuous batching 在槽位空出的那一刻就从队列补位——GPU 保持满载，利用率上升。",
  "contrastive-matrix": "CLIP 把 batch 里每张图与每条 caption 两两打分，形成相似度矩阵。对比损失把匹配的对角线对拉近、把非对角推远。除以一个小的温度，softmax 变锐、对角线亮起；温度大了矩阵摊平，模型不再分辨配对。",
  "conv-output-size": "卷积的输出空间尺寸服从一个公式：floor((W − K + 2P) / S) + 1。padding P 加边，让 kernel 够得着边缘、保住尺寸；stride S 跳位、缩小输出。「same」padding 选 P 使输出匹配输入；「valid」padding 用 P = 0、每边缩 K − 1。",
  "convex-vs-nonconvex": "凸碗只有一个极小值，梯度下降从任何起点都能到达。非凸地形有好几条山谷：灰色轨迹滚进离起点最近的那个，橙点可能落在一个并非全局最优的局部极小值里。拖动起点，看不同的盆域如何捕获路径。",
  "convolution-kernel": "卷积把一个小 kernel 盖在图像每个 3x3 patch 上、求逐元素乘积的和。边缘 kernel 抵消平坦区、点亮竖直条带；blur 对邻居取平均；sharpen 让中心相对周围放大。输出每边小两个像素——因为窗口无法在边界上居中。",
  "coref-links": "三种表面形式——「He」「the CEO」「Cook」——都指向同一个人。共指消解从每个 mention 画一条链回到同一个簇，下游的 NER、QA 和知识图谱因此把它们当作一个实体。",
  "cosine-similarity": "embedding 之间比的是角度，不是距离。两个向量同向时 cosine 为 1，正交（无关）为 0，相反为负。模长被约掉——所以长文档和短查询照样能匹配。",
  "cost-governor-stack": "单一月度上限只在钱包烧穿后才抓得住失控 Agent。解法是一摞不同时间尺度的限额——按请求、按任务、速率、按天、按月。失控循环烧得飞快，所以速率限额（「10 分钟 50 美元」）远在天/月上限点火之前就绊响。",
  "cost-per-token": "serving 经济学归结为两个数：GPU 每小时多少钱，这一小时产出多少 token。每百万 token 成本等于时价除以每小时服务的 token 数、再按一百万缩放。吞吐翻倍，单价减半——batching、量化、更快的 kernel 全都直接换算成更低的每 token 价格。",
  "cot-decomposition": "硬问题要求直接给答案，等于逼模型把所有步骤压进一次跳跃，它常常滑倒。Chain-of-thought 让它把中间步骤写出来，一次大跳变成一串各自容易的小跳。每个可见的子步骤还是模型自查自纠的机会。",
  "cross-attention-fusion": "vision-language 模型里，每个文本 token 是一个 query，对图像 patch 的 key 做注意。网格就是一张注意力图：行是文本 token，列是图像 patch，每行 softmax 归一。「bird」这类实词聚到包含那物体的 patch 上——语言就是这样 grounding 到像素的。",
  "cross-entropy-loss": "交叉熵收取模型压在正确答案上的概率的 −log。又对又自信几乎免费；又错又自信倾家荡产。正是这种不对称逼着模型学会校准，而不只是答对。",
  "ctc-collapse": "CTC 让声学模型对每帧发一个标签，而不需要知道对齐。解码按顺序跑两步：先把连续相同符号折叠成一个，再删掉 blank token。blank 至关重要——它隔开两个真实的「l」帧，「hello」的两个 l 才不会被合并成一个。",
  "cv-diffusion-image": "diffusion 模型学的是一次去掉一点噪声。采样从一片纯高斯噪声的网格出发往回走：每步预测噪声并减掉它，结构逐渐浮现。小的去噪步重复足够多次，一张连贯图像就从雪花里凝结出来。",
  "cv-gan-image": "generator 把噪声向量变成图像；critic 打分它看起来多真。两者互相对抗训练：generator 把 critic 的 P(real) 推上去，critic 把它压下来。跷跷板趋向平衡，假图像从噪声中磨出结构。",
  "cv3-ctc-collapse": "CRNN 每个时间步发一个字符（或 blank ε），与输入没有固定对齐。CTC 定义了折叠规则：先合并连续相同标签，再删 blank。两个 l 连续段之间的 blank 正是「hello」不塌缩成「helo」的关键。训练时对所有能折叠成目标的对齐求和。",
  "cv3-gaussian-splat": "一个场景是数百万个 3D Gaussian，各自携带中心、旋转+缩放的协方差、不透明度和随视角变化的颜色。渲染把每个椭球投影成 2D 椭圆，按深度排序，从前往后 alpha 合成——这正是 NeRF 当年要几百次 MLP 查询才能逼近的混合。所以 splat 能以 100+ fps 渲染、几分钟训完。",
  "cv3-latent-compression": "像素空间的 diffusion 每步要反传过 786,432 个数值。Stable Diffusion 训练一个 VAE，把 3×512×512 的图像压成 4×64×64 的 latent（小橙色网格），整条去噪循环都在 latent 里跑，最后再解码回像素。latent 上的注意力便宜 48 倍——开放权重 text-to-image 由此变得可行。",
  "cv3-open-vocab": "Promptable Concept Segmentation 收下一个简短名词短语，一遍跑完就返回所有匹配物体的 mask 和实例编号。灰色的苹果和盒子不选中；三个橙子被描边并编号。早先的系统要把文本 grounding 检测器串上另一个分割器，接缝处误差累积。SAM 3 把这条级联压成一个模型。",
  "cv3-pose-heatmap": "姿态模型不直接回归坐标。它为每个关键点输出一张 heatmap，训练目标是让高斯凸包正好盖住真实关节，argmax 像素即坐标。K 个峰全部浮现后，关节按固定的人体图（top-down）或 association field（bottom-up）连成骨架。",
  "cv3-rectified-flow": "DDPM 学的是从噪声到数据的弯曲轨迹，忠实积分它要几百个小步。rectified flow 训练模型直接走噪声样本与数据点之间的直线。直路需要的积分步数少得多——SD3 和 FLUX 因此 20 步采样（蒸馏后 1–4 步），而不是 1000 步。",
  "cv3-roialign-sampling": "RoIPool 两次把 proposal 框吸附到整数特征网格上，每次取整都让 mask 糊掉零点几个像素。RoIAlign 保持框的小数坐标：在每个输出 bin 里放固定数量的采样点，逐点对四个相邻格子做双线性插值取值。没有取整，mask 就落在物体真实所在的位置。",
  "cv3-track-assoc": "tracking-by-detection 每帧跑一次检测器，然后判断哪个新框对应哪条旧轨迹。它按 IoU（常再叠加运动与外观）给每对（轨迹，检测框）打分，用匈牙利算法解指派，把匹配上的 id 带到下一帧。落单的检测框开新轨迹；落单的轨迹逐渐老化退出。产品要的是身份，不是框。",
  "data-augmentation": "增广对每张训练图像施加保持标签的变换——翻转、旋转、裁剪、色彩偏移——一个有标签示例变成许多个。网络从不会两次见到完全相同的输入，学会的特征能在这些变化下存活——等效数据集因此扩大，过拟合被抑制，还不用多收集一条数据。",
  "data-parallel": "每张 GPU 持有完整的模型副本，处理全局 batch 的不同切片。backward 之后，all-reduce 把所有 GPU 的梯度求和，副本保持一致。吞吐量随 GPU 数接近线性扩展，但内存并不下降——每张卡仍然存着整个模型。",
  "debate-converge": "独立的模型实例各自提出答案，然后互相阅读、批评，数轮之间向一致更新。浮出错误的是分歧，而不是一条单独的 chain of thought。稀疏拓扑（不是图示的全连接）能用几分之一的 token 成本打平准确率。",
  "decision-tree-depth": "深度每加一层，叶子翻倍、树能刻出的区域翻倍再翻倍。前几刀抓住真实结构；再往下叶子变金——树在逐点硬背，而不是学模式。",
  "demo-token-bucket": "每个请求从它所属 client 的桶里取一个 token。桶以固定速率补充、存量从不超过容量。容量定下 demo 接受的最大突发；补充速率定下稳态请求速率。被拒的请求拿到带 Retry-After 头的 HTTP 429，模型不会运行。",
  "dependency-arcs": "dependency parsing 从每个词向它的 head 画一条带标签的弧。动词「running」是 root；「cats」是它的主语、「were」是它的助动词，介词短语挂在动词上。每条边都是一个（head, dependent, relation）三元组。",
  "depth-sweep": "单目深度模型把一帧 RGB 映成每个像素的距离。冻结的 ViT encoder 读出透视、纹理和学到的场景先验；轻量 decoder 把它们上采样成稠密深度图。近处表面发亮、远处退暗——全凭一张图，不用立体相机或深度传感器。",
  "derivative-tangent": "导数是切线的斜率。对 f(x) = x³ − 3x，它等于 3x² − 3，在 x = ±1 处为零——那两个临界点上橙线放平。两点之间函数下降，两点之外上升。梯度下降读的正是这个斜率来决定往哪边走。",
  "dgm-archive": "DGM 丢掉形式化证明，留下一座开放式档案馆。每个 Agent 给自己的源码提议修改、跑 benchmark 打分、过线就保留。血统向前分叉，最高分一路爬升——SWE-bench 就这样从 20% 涨到 50%。同样的开放性也让它学会了钻自己 evaluator 的空子。",
  "differential-attention": "差分注意力计算两份独立的 softmax 映射，把第二份乘以学到的 λ 后从第一份里减去。两份都携带同样的宽泛注意力噪声，减法把它当共模消掉，而真正的信号峰（这里是 token 2）存活。λ 调大，减得更狠——注意力质量因此收拢到相关 token 上，不再摊在无关上下文里。",
  "diffusion-denoise": "diffusion 模型学的是逆转加噪过程。t = T 时信号是纯噪声；t 一路降到 0，模型逐步去噪，底下的信号（灰色虚线）重新浮现。每个 x_t 都是干净信号与同一份噪声的固定混合，权重由 schedule 决定。",
  "discount-horizon": "t 步之后的 reward 按 gamma^t 加权，权重几何式衰减（长条）。虚线是有效视野 1/(1 − gamma)，权重在那里降到约 1/e。调大 gamma，视野拉长，Agent 开始在乎遥远得多的未来 reward。",
  "dpo-loss": "DPO 跳过单独的奖励模型：直接训练 policy，让 chosen 的得分超过 rejected——两者都相对一个冻结的 reference 度量。损失是 β 倍该差距的 −log σ。正差距（chosen 领先）把损失推向零；负差距产生大梯度。β 控制隐式 KL 约束把 policy 往 reference 拉回的力度。",
  "dpo-margin": "DPO 直接在偏好对上训练，没有单独的奖励模型。损失是 β 倍 chosen 与 rejected 之间隐式 reward 差距的 −log σ。正差距越大损失越接近零；负差距（rejected 排更高）重罚。",
  "draft-verify-tokens": "便宜的 drafter 用几次小前向快速提出多个 token。大模型随后一次前向验证全部：接受与自己分布一致的最长前缀，拒绝其余。草稿质量好时，一次大步的价钱换来多个 token——输出分布分毫不变。",
  "dropout-mask": "Dropout 每步把比例为 p 的单元清零，网络因此无法依赖任何单个单元。因为只有幸存者传递信号，它们被放大 1/(1−p) 以保持期望 activation 不变；测试时整层全开、不再缩放。",
  "edge-bandwidth-pipe": "decode 每 token 都要读全部权重，所以天花板是内存带宽，不是算力。数据中心的 HBM3 近 3 TB/s，约一毫秒就能冲一遍权重，每秒吐几百 token。手机 DRAM 只有 50–90 GB/s，管道窄 30–50 倍——同一个模型不管 NPU 算力闲多少，都只能 14–25 tok/s 细水长流。",
  "edit-distance": "Levenshtein distance 填一张表，每个格子是「用 insert、delete、substitute 把一个前缀变成另一个」的最省路径。每个格子取三个邻居的最小值，右下角就是整串的距离。回溯选择就还原出实际编辑路径——拼写检查器和翻译指标就是这样对齐文本的。",
  "eigen-directions": "对对称矩阵而言，特征向量就是虚线轴，矩阵只是把沿轴的东西按特征值拉伸（橙色）。不在轴上的普通灰色向量，则一边拉伸一边旋转成蓝色的像。拖动它的角度：只有落在特征轴上时，输出才与输入保持平行。",
  "elf-byte-map": "条带按比例画出整个目标文件——左端 offset 0x0，右端最后一个字节。蓝色是选中的结构或函数，浅蓝是容纳选中函数的 section，灰框是其他结构，空白是闲置空间。条带下方的行是选中内容的真实字节——每行 16 个，左侧是文件 offset。",
  "encoder-decoder": "encoder 把整段源文本读一遍，冻结成一个稠密表示。decoder 再逐 token 生成输出，每一层都 cross-attention 进那个表示。翻译、摘要、转写——都是同一种「输入到输出」的形状。",
  "entropy-kl": "熵 H(p) 度量蓝色分布的平均意外程度，四个格子相等时最大。KL(p‖q) 度量用为 q 构造的编码去编码 p 的样本要多付的比特；它非负，仅当两者相同时为零，且不对称。交叉熵训练最小化的正是这个差距。",
  "epsilon-greedy": "Agent 以 epsilon 概率随机探索一个动作，否则按当前最优估计利用。长条显示 explore/exploit 的配比，曲线是累计 regret——没有永远选最优臂而放弃的那部分 reward。固定 epsilon 的 regret 永远堆积；衰减 schedule 先探索后利用，regret 走平。",
  "eval-grid": "runner 读任务 spec，把任务撒进 worker pool，用 metric 层加校准报告逐一打分。扫过之处格子点亮 pass（蓝）或 fail（橙）。每个模型的 EvalRun 记录直接流进 leaderboard aggregator；demo 在一次干净的运行后自行终止。",
  "eval-harness-matrix": "eval harness 让每个任务对着每个模型变体跑，把 pass/fail 记进网格。顺着列读，看出哪些任务难；顺着行读，给一个变体算出总分。这张矩阵把模糊的直觉变成一个能拿去做回归测试的数字。",
  "expert-capacity": "MoE 层里每个 expert 分到固定数量的 token 槽位，由 capacity factor 决定。路由不均，热门 expert 溢出，多出的 token 被丢弃（虚线上方的橙色）。factor 太低，丢很多 token；太高，轻负载的 expert 闲置、padding 算力被浪费。调 factor 就是让两头都小。",
  "expert-routing": "dense block 给每个 token 都跑同一个 FFN。MoE block 换成许多 expert FFN 加一个 router，每个 token 只送到其中 top-k 个。总参数随 expert 数量增长，每 token 的算力却只随 k 增长——模型变大而不变慢。",
  "f3-anomaly-fence": "有标签的异常太少，学不会「异常长什么样」，于是检测器改学「正常」的形状：普通点居住的稠密区域。落在围栏之外的任何东西都会被标记，无论它是哪种异常。这就是该方法不需要异常标签、却仍能抓住从未见过的失败模式的原因。",
  "f3-bootstrap-resample": "bootstrap 把你的样本当作总体的替身。有放回地抽 n 个点、计算统计量、重复数千次：得到的 bootstrap 均值分布展示了单凭采样噪声就会带来多大抖动。它的中间 95% 区间就是一个不需要正态假设的置信区间。",
  "f3-dqn-stability": "让 deep Q-learning 收敛的三个技巧中的两个。transition 流入回放缓冲区，训练时随机采样，连续更新之间便不再相关。同时琥珀色的目标网络在在线网络训练期间保持冻结，每一万步左右才快照一次新副本，让 Bellman 目标追不上自己。",
  "f3-ensemble-average": "每条灰色曲线都是一个弱学习器：高方差、各自错得不一样。因为它们的错误（部分）相互独立，取平均就能抵消噪声、保留共享信号，蓝色的集成比任何成员都更贴近真实模式。Bagging 构造的正是这个；多数投票是同一套抵消用在类别标签上。",
  "f3-feature-prune": "按每个特征对目标的信息量打分（这里是互信息），阈值把信号与噪声切开。矮柱淡出：丢掉它们缩小了特征空间，距离保持有意义，模型需要的数据更少，对噪声列的过拟合随之消失。filter、wrapper 与 embedded 方法只在分数怎么算上不同。",
  "f3-learning-boundary": "这里没有人写 if 语句。分类器用每个有标签聚类的质心来概括它，决策边界从几何中自然浮现：两个质心的垂直平分线。换一份数据，就浮现另一条边界。这种倒置——规则从例子中推导而非手写——正是它叫机器学习的原因。",
  "f3-marl-orbit": "左：同一世界里的两个独立学习器。每个都把对方当作环境的一部分，于是任何一方的更新都让另一方的价值估计失效——两个策略永远绕圈，这是非平稳性陷阱。右：给训练一个能看到联合状态与联合动作的集中式 critic，同样的动力学便向内旋成稳定的联合策略。",
  "f3-pipeline-flow": "pipeline 把所有变换和模型链成一个对象：样本以原始形态进入，每一站重塑它再交给下一站。所有统计量（中位数、均值、类别映射）只在训练数据上拟合一次，然后冻结。服务运行同一条链——正是这一点堵死了数据泄漏和 train-serve skew。",
  "f3-reality-gap": "在固定仿真器里训练出的 policy，在每个物理轴上都离真实系统有一段距离——这段距离就是 reality gap。域随机化把训练包络拓宽：每个 episode 采样不同的质量、摩擦、延迟和光照。一旦包络覆盖真实机器人的参数，现实就只是 policy 早已能处理的又一个样本。",
  "f3-selfplay-ladder": "同一个循环驱动着 AlphaZero、MuZero 与 GRPO：当前策略与自己博弈，搜索（或验证）把这些对局变成更好的动作分布，网络再朝着搜索的发现训练。绕三角的每一圈都为下一圈造出略强的对手，棋力便沿着台阶爬升，全程不需要任何人类数据。",
  "f3-series-decompose": "观测到的序列是三个更简单信号的叠加：缓慢的趋势、重复的季节周期，以及剩下的残差。分解把它们拆开，各自按各自的方式处理：去趋势、去季节，得到平稳性，再对残差建模。扫过的线提醒你各部分在时间上逐点对齐。",
  "failure-cascade": "Agent 的失败不是随机噪声，它们落入反复出现的模式。级联错误代价最高：一个幻觉步骤写进下一步的输入，一个错误动作沿 plan、retrieval、reasoning、action 层层传播。给模式命名，你才能监控它、并及早剪断链条。",
  "feature-scaling": "特征尺度悬殊时，损失面是一道狭长峡谷，gradient descent 在两壁间弹跳。把每个特征标准化到零均值单位方差，碗变圆了——同一个算法几乎直线走到最小值。",
  "few-shot-curve": "往 prompt 里加有标签示例，准确率先快速上升然后走平。灰点是 zero-shot；头几个 demonstration 就关掉了大部分差距，超过五六个之后，每个新示例几乎不涨分、却照样花 token。功力在于挑出到达平台期所需的最小集合。",
  "flash-attention-memory": "标准 attention 要把完整的 N×N 分数矩阵写进内存，开销随序列长度平方增长、很快盖过一切。FlashAttention 分块计算、从不物化那个矩阵，内存随长度线性增长。两条曲线迅速拉开：长上下文时省的是数量级。",
  "fourier-synthesis": "每个周期信号都是基频整数倍正弦波的叠加。淡灰曲线是各个奇次谐波；蓝线是它们的和。把幅度设为 1、1/3、1/5、1/7，和就开始朝方波收拢——这是傅里叶级数逼近方波的经典画面。",
  "function-call-args": "function calling 是两份工作合在一起。模型先从可用集合里选出要调用的工具，再从用户请求里抽取值、填进该工具的类型化参数 schema。输出不是散文而是一结构化调用：工具名加一个 JSON 对象，字段类型与声明一致，拿来即执行。",
  "gan-minimax": "GAN 是两人博弈：generator（蓝）设法骗过 discriminator（灰），discriminator 设法分辨真假。两者必须一起变强。discriminator 大获全胜，它给 generator 的梯度就消失；generator 一骑绝尘，又可能坍缩到少数几个输出上。健康的训练停在虚线标出的均衡附近。",
  "gaussian-pdf": "均值把钟形曲线左右滑动；标准差决定它的宽度。σ 越小，峰越高越窄，因为总面积恒为 1。阴影带是 μ ± σ——无论曲线放哪，它总是兜住约 68% 的概率。",
  "gpu-memory-breakdown": "训练内存远不止权重。混合精度 Adam 里，每个参数要付：fp16 权重两字节、梯度两字节、优化器状态约十二字节——所以在第一个 activation 出现之前，固定成本已约每参数十六字节。activation 再随 batch 大小增长。这就是为什么推理装得下的模型，单卡训练可能远远装不下。",
  "gqa-kv-sharing": "每个 query 头保留自己的投影，但多个头可以共享一个 key-value 头。每个 query 一个 kv 是完整 multi-head；全体共用一个是 multi-query；中间按组共享就是 grouped-query attention。kv 头变少，cache 按 query 头与 kv 头之比缩小，质量基本保住。",
  "grad-clip-monitor": "每一步都测全局 gradient 范数并裁到上限。一个溢出的 batch（橙）会冲破上限、把损失打成 NaN；GradScaler 检测到 Inf，跳过这一步优化器更新，并把 scale 减半——运行因此存活。",
  "gradient-clipping": "gradient 范数突然飙升时，一步就能把权重扔下悬崖。clipping 把任何范数超过阈值 τ 的 gradient 等比缩回 τ：方向不变，幅度封顶。τ 以下原样通过；τ 以上更新被驯服为 min(‖g‖, τ)。",
  "gradient-descent": "每一步沿梯度乘学习率的方向下山。太小则爬行；太大则越过谷底、发散。训练就是在两者之间寻找那个学习率。",
  "graph-degree-distribution": "每条边接触两个节点，给每个节点的度各加一。把所有节点的度加起来，每条边恰好被数了两次。这个握手引理对任何图都成立，并迫使奇数度的节点数量必为偶数。",
  "guardrail-gates": "安全以有序闸门运行：模型前的输入过滤器、请求上的 policy 检查、响应上的输出过滤器。第一道绊响的闸门就拦下请求——不安全 prompt 到不了模型，不安全输出到不了用户。",
  "gx-entity-linking": "实体链接分两阶段。候选生成把「Jordan」这个表面形式可能指向的每一个知识库条目都拉出来；消歧再用上下文给每个候选打分，留下一个。这里的体育语境把 mention 解析到篮球条目，演员、国家、ML 教授候选渐隐退场。",
  "gx-fid-distributions": "FID 不逐张打分。它在 Inception 特征空间里分别对真实图像和生成图像拟合高斯，再通过均值和协方差度量两个分布之间的距离。生成云团逐渐盖住真实云团，距离——也就是 FID——落向零。",
  "gx-hybrid-retrieval": "生产级检索是一条链，不是单一方法。稀疏 BM25 钉死精确关键词；稠密向量接住换一种说法的查询；Reciprocal Rank Fusion 只看排名位置就把两份排序表合并——分数刻度不兼容也无妨；cross-encoder 再把 query 和文档放在一起读，对幸存者重排。最终的第一名可以不同于任何一路输入。",
  "gx-matryoshka": "Matryoshka 训练的 embedding 把最重要的信息装进最前面的维度。只保留向量的前缀也照样能检索——3072 个浮点数砍到几百个。截断把索引存储省下数倍，质量是渐降而不是崩塌，于是你可以按成本目标调维度预算。",
  "gx-niah-decay": "needle 测试在长上下文的指定深度埋一条事实，再让模型把它找出来。短上下文里的浅层 needle 几乎百发百中；事实埋得越深、干草堆越长，准确率仪表越往下掉。宣传的上下文窗口很少等于可用的那个——这正是 depth-by-length 扫描重要的原因。",
  "gx-patchgan": "PatchGAN 不给整张图输出一个真假分。它让固定大小的感受野扫过输出，独立评判每个局部 patch，产出一个 NxN 的判定网格再取平均。真实感被当成局部属性——discriminator 因此更小、更快，对高频纹理也更敏锐。",
  "gx-stylegan-mapping": "普通 generator 把噪声向量 z 直接喂进网络，各种变化因子纠缠在一起。StyleGAN 先把 z 过一个 8 层 MLP，映射到中间空间 W——它的轴对齐姿态、光照这类有意义的因子——再在每个分辨率经 AdaIN 注入 w。先解缠，风格混合与编辑才成为可能。",
  "gx-var-next-scale": "VAR 以分辨率序列生成图像，而不是按 raster 顺序逐像素。它先预测 1×1 的 token 概要，再 2×2 网格、4×4、8×8，每个尺度一次并行前向完成，且以前面所有更粗的尺度为条件。逐像素模型的生成顺序难题就此消失。",
  "htn-tree-expand": "HTN planner 把复合任务展开成方法，每个方法再展开成子任务，递归到每个叶子都是前置条件成立的原子 operator。树自顶向下长出；计划就是原子叶子的从左到右读序。",
  "i4-canary-ramp": "影子模式把生产请求复制给候选版本、丢弃它的答案——在零用户风险下抓住成本尖峰和分布漂移。然后才开始 canary 爬坡：10、25、50、100%，每一步都由延迟分位数、每请求成本、拒答率、输出长度分布和用户反馈把关。回滚是一次以秒计的策略翻转，绝不是一次重新部署。",
  "i4-chaos-guard": "控制面朝目标注入故障：429 风暴、KV cache 逐出、网络中断。安全面全程盯着错误预算的燃烧速率表。当日燃烧率越过预期的两倍，guard 在实验半空中中止，最后一个故障永远不会落下。没有这根绳子的混沌工程，只是一场你自愿报名的宕机。",
  "i4-control-matrix": "采购方想要一张每个框架一行的矩阵，活下来的办法是交叉映射。一套访问控制的实现同时点亮 SOC 2、GDPR 第 32 条、HIPAA 164.312(a) 和 ISO 的格子；PII 脱敏与审计日志各扫一列。每个控制只建一次、多次声明——五个框架的成本远低于五次审计，剩下的缺口也明显是框架特有、而非到处都是。",
  "i4-incident-agents": "告警落在 supervisor Agent 上，它把查询分派给专家：一个 grep 日志，一个把指标关联到部署，一个匹配 runbook。在任何人打开 dashboard 之前，证据已经汇成一个假设。修复动作仍要过人工审批闸门；自主权限保持很窄：重启一个 pod、回滚一次部署——凌晨 3 点绝不重新架构整个服务。",
  "i4-otel-glue": "没有一个可观测性工具能同时赢下两份工作，所以生产模式把它们拆开。网关把每次 LLM 调用捕获成 OpenTelemetry span；collector 把每个 span 克隆到两个汇：遥测后端管 trace、延迟和成本，评估平台管漂移和 RAG 质量。日后换掉任何一侧都是改配置，不是重新埋点。",
  "i4-platform-lanes": "超大规模厂商的延迟差距是容量问题，不是模型问题。Azure PTU 预留吞吐，请求走在专用车道上，中位数约 50 ms。Bedrock 按需模式与其他所有租户共享一个池子，同规模模型读出约 75 ms——因为你的 token 排在别人后面。先按目录和 FinOps 界面选平台，再决定哪些工作负载配得上预留车道。",
  "i4-spend-ladder": "每笔调用在创建时就被盖上 tenant_id，开销当场落进正确的仪表，而不是事后补标签。租户 A 和 B 在各自日上限内正常填充。租户 C 冲破上限线，开销 z 分数越过 4，kill switch 以 429 应答，同时 on-call 被呼。这条梯子依次是：速率限制、开销上限、kill switch——爆炸半径始终锁在一个仪表之内。",
  "i4-vault-rotation": "凭据只住在 vault 里。应用调用 AI 网关，网关在运行时拉取当前密钥——没有任何服务握着静态 secret。密钥 v1 滚动到 v2 时，替换发生在一个地方，所有调用方几分钟内拿到新值：不重新部署、不改 40 份配置文件、不发「谁拿到新密钥了」的消息。90 天轮换政策不再是迁移，而是一次无事发生。",
  "image-patch-tokens": "Vision Transformer 把图像切成固定大小的 patch 网格，每个 patch 当作一个 token——和文本里的词完全一样。token 数是（尺寸÷patch）的平方，所以 patch 尺寸减半，序列长度和注意力成本翻四倍。",
  "injection-boundary": "浏览器 Agent 读不可信的网页、执行后果重大的动作。每页都是用户没写过的输入，所以每行内容都是一条瞄准「读与做」模糊边界的潜在命令。防御能弹开大多数尝试，但间接 prompt injection 就活在那条边界里——正如 OpenAI 所说，它「不是能被彻底补丁修掉的 bug」。",
  "injection-gate": "prompt 流过三层可审计的防线：normalize 解掉 base64/rot13/零宽字符把戏，substring 规则抓手写短语，regex 规则抓整个家族。良性 prompt（蓝）干净通过；攻击（橙）绊响一条规则，aggregator 发出的是置信度和类别，而不是一种感觉。",
  "injection-hijack": "间接 prompt injection 把指令埋进 Agent 检索到的内容里。模型无法可靠区分用户意图与检索文本，恶意 token（红）就把 Agent 劫持到攻击者选定的工具。把所有检索内容当成 tool-use 表面上的任意代码——任何调用提交前先校验。",
  "inpaint-mask-reinject": "inpainting 只对被 mask 的区域去噪，同时在每一步重新注入已知像素，边界因此保持一致。行进的虚线是 mask 边缘；内侧噪声解析成新内容，周围的上下文被按死、逐像素不变。",
  "interpretability-probe": "线性探针是一个简单分类器，学着从某一层的 activation 里读出某个概念。探针准确率接近随机说明该概念在此处不可线性解码；准确率高则说明可以。把探针沿网络走向深处，就能看到概念逐渐变得线性可读——可解释性研究者就是这样定位「欺骗意图」这类特征首次出现的位置。",
  "jailbreak-defense": "拦截对抗性 prompt 的安全过滤器，同样冒着误杀无害请求的风险。防御强度调高，琥珀色的攻击成功曲线下降，蓝色的过度拒绝曲线却随良性请求被拦而上升。没有免费午餐：工作点选在拐点处——拦下绝大多数 jailbreak，又不拒绝太多合法用户。",
  "k-fold-cv": "每行是一轮：金色折留作验证，蓝色折用于训练。轮换留出折，每个样本恰好被打分一次；k 个分数取平均，比单次切分稳定得多。",
  "kmeans-step": "K-means 在两步间交替：把每个点分给最近的 centroid，再把每个 centroid 挪到自己成员的均值。簇内平方和只会下降，所以一旦没有点再换簇，算法就收敛了。",
  "knn-smoothness": "k = 1 时预测完全照抄最近的点，曲线锯齿丛生、迁就每一个怪癖。k 调大，预测在更多邻居上取平均，边界随之平滑；k 极大时曲线摊平到整体类别比例，彻底无视局部结构。",
  "kv-cache-sizer": "缓存为每个 token、每层、每个 kv-head 保存一个 key 和一个 value。它随序列长度和 batch 线性增长——把 GPU 填满的是高 batch 下的长上下文，不是权重。",
  "l2-regularization": "L2 把权重范数的平方加进损失。调大 λ 把每个系数往零拉、让模型更平滑。太小则过拟合；太大则连信号一起忘掉。",
  "l5-data-pipeline": "数 TB 的原始文本流过去重和质量过滤，然后被打包成定长序列。只有一小部分存活下来，而且 pipeline 产出 batch 的速度必须快过 GPU 消耗的速度，否则整个集群都在等 dataloader。",
  "l5-emu3-next-token": "Emu3 用一个 Llama 风格的 decoder、以 next-token prediction 在一份共享词表上训练——文本、VQ 图像 token、3D 视频 token 都只是词条。没有 diffusion 调度，没有 CLIP 损失，没有第二目标。同一颗头扫过同一套词表，能写一句话、一张图或一段视频，所以同一个模型可以既是 Emu3-Chat 又是 Emu3-Gen。",
  "l5-framework-fit": "每个框架都有一个核心抽象，也就是你会在白板上画的那个东西。LangGraph 画的是状态图，CrewAI 画的是组织架构图，AutoGen 画的是对话，Agno 画的是单个 Agent 挂着 tools。选画的图和你问题匹配的那个；硬套错误的形状意味着你要亲手把缺失的抽象补写两遍。",
  "l5-janus-decouple": "理解要语义特征，生成要利于重建的编码，一个编码器伺候不了两头。Janus-Pro 让理解走 SigLIP、生成走 VQ tokenizer，而两个任务共享同一个 transformer 主体。两扇前门、一条大厅，谁也不用替谁交质量税。",
  "l5-native-pretrain": "事后补训先铺数万亿文本 token，最后把视觉粘上去；接缝就是 alignment 债——灾难性遗忘、答案漂移、视觉与文本不一致都是它的样子。InternVL3 从第一步起就把文本、交错图文和 caption 数据放在一起训练，视觉 token 是这面墙的原住民，而不是外挂的扩展间。",
  "l5-onevision-budget": "LLaVA-OneVision 把视觉 token 预算大致钉在每样本几千 token，然后只是重新打包：一张图用高 AnyRes 分辨率，多图用中等分辨率，32 帧视频池化到每帧 81 token。因为三种场景成本几乎相同，一个模型就能在全部三种数据上训练，谁也不会压过谁。",
  "l5-prod-app-paths": "一个请求错过所有缓存、走完整条路：guardrails、检索、模型本体——数秒延迟、全额 token 成本。片刻后一个一模一样的请求在缓存处短路，几毫秒内几乎零成本返回。生产 LLM 工程的很大一部分，就是把第二条路变成常态。",
  "l5-spec-decode-eagle": "draft head 提议四个廉价的 token。一次 verifier forward 同时给全部四个打分：一致的前缀被接受，第一个分歧处被拒绝、换成残差分布的采样，其后所有内容被丢弃。全部接受时 verifier 还会多发一个奖励 token，所以一次大模型 forward 可以产出 N+1 个 token，且 verifier 分布分毫不差。",
  "l5-state-graph-ledger": "同一个 ReAct loop 画成显式的图。游走者穿过模型、tools 和人工审批节点，每次转移都往下面的 ledger 写一个 checkpoint。走到人工节点，执行干脆停住：状态已经持久化，图可以稍后恢复，也可以倒回任意更早的 checkpoint、沿另一条路分叉下去。",
  "l5-thinker-talker": "Qwen2.5-Omni 把语音 pipeline 拆开：大的 Thinker 以文本 token 写出回复，小的 Talker 并行把它们转成语音 token，只落后一两个 token。第一段音频到达扬声器时，整句话大部分还没写完——往返时间因此压在 500 ms 会话阈值之内。",
  "l5-vlm-recipe-knobs": "这条排序在 MM1、Idefics2、Cambrian-1 与 Prismatic 的消融表里都成立。数据配比挪动 benchmark 最多，图像编码器次之，而 connector——大多数论文痴迷的旋钮——影响最小。VLM 表现不佳时，先推最高的那根推子。",
  "langgraph-state": "有状态图把 Agent 建模成节点加边，一个共享 state 对象贯穿每个节点。每个节点读状态、干活、写回。条件边按状态分支，评分不及可以绕回重写而不是收工。图让控制流显式、状态步步可查。",
  "learning-curves": "灰色是训练损失，蓝色是验证损失。容量越大训练损失越低，但验证损失触底后随模型开始背噪声而回升。不断张开的缺口就是过拟合信号；金线标记 early stopping 会冻结模型的位置。",
  "lifting-stages-percent-change": "蓝色标记来自 ledger.c 第 3 行（那个除法）的字节、指令、IR 语句、SSA 值和 C 行。黑色标记第 2 行的零守卫。灰色标记 block 标签、花括号和签名——它们没有源行。面板下方的计数由屏幕上的行算出。十六个字节里有九个变成一行 C。",
  "linear-regression-fit": "每根橙色杠杆是一个 residual——点到直线的差距。平方求平均就是 mean squared error。最小二乘无非是挑出让这个平均最小的斜率和截距。",
  "linear-system-conditioning": "二元一次方程组是两条直线的交点。两线以大角度相交，解锐利而稳定；它们趋于平行时行列式收缩、条件数爆炸，输入的微小变化把交点甩出很远。病态系统放大噪声。",
  "llm-judge-rubric": "LLM judge 按多个标准给回答打分——这里是有用性、正确性、安全性。总分是加权平均，权重编码了你真正在乎什么。这份回答安全性高分、正确性低分，rubric 若向正确性倾斜，它的分数就被拉下来。决定「好」的含义的是权重，不是模型。",
  "load-pattern-waves": "四种负载形状抓四种故障。稳态测基线吞吐；ramp 爬坡到崩溃点；spike 突然冲高、测 autoscaling 反应多快；soak 长时间压住负载、让内存泄漏现形。所有请求都一模一样时，通用测试工具还会撒谎——真实流量需要可变输入长度和多样的前缀。",
  "logistic-sigmoid": "logistic regression 把线性分数过一遍 sigmoid 压成概率。权重控制曲线转折多陡；偏置把它左右平移。橙线是决策边界——概率穿过一半的位置。",
  "logsumexp-stability": "直接算 log(sum(exp(x)))，任何 logit 一旦超过约 709 就溢出——exp 超出 float64 范围。先减去最大值，把最大的项挪到 exp(0) = 1，和保持有限。结果完全相同，因为减掉的最大值在 log 外面加了回来。",
  "lora-params": "LoRA 冻结 d×d 的权重，只训练一个低秩增量 B·A——仅 2·d·r 个参数。可训练比例是 2r/d，所以在 4096 维模型上 rank 取 8，训练的权重不足百分之一，质量却大体保住。",
  "loss-masking": "一条对话样本包含 system、user、assistant 轮次，但模型只应该被训练去产出 assistant 轮次。loss masking 把所有 prompt token 的梯度清零——模型学会的是回答，而不是背下并复述问题。",
  "lost-in-the-middle": "把唯一相关的事实埋进长上下文：它靠近开头或结尾，模型记得很好；落在中间，成绩差得多。准确率随位置呈 U 形。所以 context engineering 把最重要的材料放在 prompt 的顶端或底端，绝不依赖一长段无结构的倾倒。",
  "lr-schedule": "学习率很少一直固定。短暂 warmup 避开早期不稳定；随后 cosine 或 step 衰减把学习率退火到零，让训练后期落进一个好的极小值。",
  "lstm-gates": "LSTM 的 cell state 是一段由门编辑的记忆。forget gate 擦掉旧状态的一部分，input gate 写入新候选的一部分，两者相加成为下一个 cell state；output gate 再控制多少状态泄漏成隐藏向量。门取值接近零或一时，cell 能把一个值持有许多步而 gradient 不消失。",
  "mask-derivation": "三个面板都是同一个下三角行随机矩阵乘上序列。前缀平均把每个权重钉死在 1/(i+1)。学出来的分数让权重不均匀但静止。attention 让权重取决于 token 本身——第三个面板因此不断变动。mask 从未变过；它就是最初那个平均的循环边界。",
  "masked-diffusion-unmask": "文本 token 靠 next-token prediction 从左到右一次生成一个。图像 token 起始全被 mask、并行恢复：每一步同时预测所有被 mask 的格子，留下最有把握的、其余重新 mask。几波之后整幅图填满——步数远少于自回归的图像解码。",
  "matrix-transform": "灰色是单位正方形；蓝色是它在 M 下的像。M 的列就是基向量落到的位置。行列式 ad − bc 是那个平行四边形的有向面积：它是矩阵缩放面积的倍数，变换翻转定向时它变负。",
  "mcp-conformance-operations": "选一个 fixture 和一个 runner。workbench 把 transcript 规范化，与契约 oracle 比对，给出发布决定。",
  "mcp-contract-pipeline": "切换一处契约边界，观察 consumer 收到的是有效结果、工具错误、协议错误还是脱敏失败。",
  "mcp-nxm-collapse": "MCP 之前，每个 host 和每个 server 讲一套私有协议，是一张 N×M 集成矩阵。MCP 是中间的一份 JSON-RPC spec：写一个 server，任何合规 host 都能发现并调用它的工具、资源和 prompt。请求流入、结果流回，走同一种线格式。",
  "mcp-registry-admission": "改动一个供应链事实，然后运行 admission。结果由 publisher 证明、artifact 来源、Registry 状态、吊销记录、实时发现和 descriptor pin 推导而来。",
  "mcp-reliability-race": "选一个确定性竞态，再选择观察、关闭 in-flight 请求，还是发送 tasks/cancel。ledger 暴露出最终的持久状态。",
  "mcp-tool-call": "选一个线上案例。validator 比对镜像元数据、核对 revision、分发一个 envelope，并推导出唯一合法的响应形状。",
  "mcpa-00-blueprint-weights": "交互、执行、安全与治理四个领域合计占了蓝图的一半。如果把学习时间平均分到五个领域，最高的两根柱子就会严重投入不足。",
  "mcpa-01-spec-map": "每个实现 MUST 支持基础协议、版本控制和消息模式。授权、服务端特性、客户端特性与工具集按需添加。每个特性还带有自己的 Active、Deprecated 或 Removed 状态，这份状态与文档本身处于 Draft、Current 还是 Final 分别跟踪。",
  "mcpa-02-n-by-m": "定制胶水代码随「应用 × 系统」的组合数增长。有了统一协议，每个应用只需实现一次 client，每个系统只需实现一次 server，任意 client 在运行时即可发现任意 server。",
  "mcpa-03-envelope": "request 一定携带非空 id，notification 一定不携带，result 或 error 则回显它所响应的 id。只有当 _meta 键的第二段（按点号分隔）是 modelcontextprotocol 或 mcp 时，该键才保留给 MCP 使用，无论 mcp 本身还出现在其他什么位置。",
  "mcpa-04-stateless-requests": "Alice 与 bob 的请求被轮询分配，不固定粘在任何一个副本上。两个副本都不在内存里保存 basket 状态，而是读写同一个共享存储，以 tool call 返回的不透明句柄为键——因此无论下一个请求由哪个副本应答，答案都是对的。",
  "mcpa-05-era-matrix": "同一个探测把每个 stdio server 分入三类：modern、版本不同的 modern，或 legacy。可识别的 modern 错误绝不触发回退；只有无法识别的错误或超时才会。",
  "mcpa-06-topology": "宿主为每个 server 嵌入一个 client。files 和 notes 是本地 stdio 子进程，两者都自报名叫「primary」，因此宿主的注册表以自己分配的连接 id（files 和 notes）为键，绝不依赖自报名字。metrics 是远程 Streamable HTTP server，没有 tools 能力，所以它的 tools 永远不会被列出。files 与 notes 都声明了名为 search 的 tool；聚合器把第一个保留为规范名，第二个暴露为 notes/search。",
  "mcpa-07-discover": "server/discover 是可选且可缓存的，一次性汇总 server 能做什么。每次 tools/call 仍在 _meta 里携带自己的 clientCapabilities，并即时校验：缺少 elicitation 会得到点名它的 -32021；声明了它，调用就能完成。",
  "mcpa-08-schema-contract": "已知 tool 内部的 schema 失败会作为正常 result 返回，isError 为 true，内容是模型能读懂并纠正的信息。而 server 从未广告过的 tool 名则走另一条路，以 JSON-RPC 协议错误返回，永远不会到达 handler。",
  "mcpa-09-manifest-anatomy": "manifest 由三份文档组成：server 声称支持什么、当前实际提供什么，以及注册表如何命名它。带标记的字段、诱导性指令、没有 annotations 的 tool、暴露疑似密钥参数的 header、没有命名空间的名字——这些是评审者在第一次真实调用之前要检查的东西。",
  "mcpa-10-interaction-flow": "循环里有一条分支在线上永远看不到：被拒绝的确认在 client 发送任何内容之前就停止。在到达 server 的分支中，tool 执行错误和 input required 结果都把控制权交回模型，但只有 input required 分支会以新 id 重试并回显 requestState；协议错误也把控制权交回模型，却没有可纠正的内容，所以循环不会再次发送它。",
  "mcpa-11-tool-call": "tools/call request 指明一个 tool 及其参数；返回的 CallToolResult 携带一个由五种 block 类型任意混合组成的内容列表、可选的 structuredContent 值，以及 isError。省略或为 false 表示调用成功；true 表示 tool 遇到了模型能读懂并纠正的问题。",
  "mcpa-12-resource-read": "URI 模板展开为具体 URI，resources/read 在任何查找之前先对照 server 的 root 对它做净化。存在的资源返回携带 contents、ttlMs 和 cacheScope 的完整 result。不存在的资源或试图爬出 root 的路径则返回 JSON-RPC 错误 -32602，在 data.uri 里点名被请求的 URI——绝不是一个 contents 为空数组的成功 result。",
  "mcpa-13-prompt-template": "prompt 参数填入占位符后渲染出 PromptMessage 内容。completion/complete 为一个参数排序候选建议，一旦 context.arguments 带上了已给出的答案（例如选定的语言），候选会进一步收窄。",
  "mcpa-14-mrtr": "server 从不主动向 client 发起 request。它以 input_required 结束第一次调用，由 client 发起一个独立的第二次调用——携带新的 JSON-RPC id，逐字节回显 requestState，并附上 inputResponses。",
  "mcpa-15-deprecation-timeline": "标记 Deprecated in 2026-07-28 启动的是十二个月的时钟，而非立即删除：roots、sampling 和 logging 越过最早的移除标记后仍保持精确的线上形态；而 logging/setLevel 和 notifications/roots/list_changed 已经移除，分别由 MRTR input request 和每请求的 logLevel 键取代。",
  "mcpa-16-subscription-stream": "两个订阅共用一条通道，只能靠每次确认和通知在 _meta 里携带的 subscriptionId 区分——它对应开启该订阅的 subscriptions/listen request 的 id。普通调用的进度与最终 result 走该调用自己的响应，绝不走 listen 流，因此永远不携带 subscriptionId。取消订阅会停止它的后续消息；取消落地时已在途的那条仍会到达，必须丢弃而不是投递。",
  "mcpa-17-lifecycle": "validate 只问 tool 是否存在；在这一步失败永远是协议错误 -32602，后面不会再有 execute 或 result 阶段。execute 开始之后才发现的问题——坏参数或业务规则——都作为正常完整 result 里的 isError 返回，模型能读懂并重试。input_required 的 result 不是终点：client 应答它并以新 id 再次调用，把 validate、execute、result 再跑一遍。",
  "mcpa-18-error-taxonomy": "协议错误是 client 自己处理的 JSON-RPC 错误对象。tool 问题是 isError 为 true 的正常 result，内容是模型能读懂并据此行动的信息。两者都是合法通道；下方禁止区间的 code 无论走哪条通道都绝不合法。",
  "mcpa-19-transports": "stdio 把每条消息内联在 stdin 和 stdout 上传送，日志走单独的 stderr 行，完全没有 header 层。Streamable HTTP 把方法名、tool 或资源名以及任何 x-mcp-header 参数镜像进 header，让网关无需解析 body 即可路由——但 body 仍是唯一事实来源：与 body 不一致的 header 会在 tool 运行之前被 HTTP 400 和 HeaderMismatch（-32020）拒绝。",
  "mcpa-20-cache-freshness": "缓存的响应在 ttlMs 耗尽前保持新鲜，但一条相关的 list_changed 通知一到就立刻使其失效，哪怕 TTL 还剩很多。TTL 与通知是互补关系，不是竞争关系。",
  "mcpa-21-task-states": "每次 tasks/get 轮询都会重复同一个进行中的快照，直到出现终态；这个自环没有画出来。cancel 或协议错误也能让任务直接从 input_required 结束。SEP-2663 把完成 result 和失败 error 内联进同一个 tasks/get 响应；不存在单独的 tasks/result 调用。",
  "mcpa-22-trust-zones": "宿主与它拥有的 client 和模型处在同一个信任域。request 跨越虚线边界到达 server；server 返回的一切都要穿过信任过滤器、被标记为不可信之后，模型才会读它。server 还可能访问更上游的系统，client 无法直接观察到这些访问。",
  "mcpa-23-oauth-flow": "拒绝发生在 HTTP 层，没有 JSON-RPC body。中间那条泳道完全在 MCP 线路之外解决：Protected Resource Metadata、授权服务器元数据、PKCE，以及 client 自己执行的 iss 校验。只有重试的 tools/call——如今携带的 bearer token 其 audience 与本 server 匹配——才真正到达 tool。",
  "mcpa-24-registration-paths": "client 按顺序尝试每条路径，遇到第一个可用的就停下：预注册凭据；若授权服务器广告了 Client ID Metadata Document 则用它；然后是已标记废弃的 Dynamic Client Registration 作为回退；最后询问用户。任何路径得到的凭据都以签发的授权服务器为键保存，绝不拿去对付另一个授权服务器。",
  "mcpa-25-consent-gates": "tools/call 先遇到 scope 闸门：scope 不足会以 HTTP 403 返回，client 把旧 scope 与被质疑的新 scope 求并集后重试，次数封顶。scope 通过之后才轮到同意闸门：需要批准的 tool 会返回 input_required，client 在一轮 elicitation 往返之后重试。两个闸门各自都能独立拦下一个调用。",
  "mcpa-26-attack-surface": "每根辐条对应本课讲过的一种威胁。中央网关握有应对它们的控制措施：针对 rug pull 的定义固定与隔离、针对投毒描述的注入扫描器、对抗遮蔽的 server 限定名、对抗透传的 audience 校验、受完整性保护的状态、拒绝自动解引用网络引用，以及对抗供应链漂移的准入固定——没有任何单一控制需要独自挡住所有威胁。",
  "mcpa-27-trace-propagation": "trace id 跨越两跳保持不变，而每条箭头各自铸造自己的 span id。ops-desk 和 credential-vault 各自维护独立、按哈希链连接的审计日志：谁也不读写对方的条目，把一个 server 的条目与另一个 server 的条目关联起来的只有共享的 trace id，绝不是共享的 request id。",
  "mcpa-28-roles-map": "落地方式改变的是谁来签署一条 MUST，而不是它是否仍然适用。Origin 校验在任何 HTTP 可达的部署里都是 server 端 MUST：明文 HTTP 部署时它留在 server 作者手里；网关前置部署时它移交给最先终结连接的平台或网关运营方。",
  "mcpa-29-use-case-matrix": "四个问题——谁发起调用、数据有多敏感、要运行多久、是否需要交互界面——为本课目录中的每个用例选出原语、传输方式、auth 路径和扩展。",
  "mcpa-30-extension-negotiation": "client 在每个请求的 _meta['io.modelcontextprotocol/clientCapabilities'].extensions 里声明扩展；server 在 server/discover 的 capabilities.extensions 里声明自己的。只有双方都点名的标识符才会激活。未匹配的可选扩展回退到核心行为；未匹配的强制扩展得到 MissingRequiredClientCapability（-32021），点名缺了什么。",
  "mcpa-31-app-sandbox": "tool 的 ui:// 资源只有在宿主把它的 mime 类型与 CSP origins 对照自己的 allowlist 检查通过后，才会成为沙箱化 app；任一检查失败，或根本没声明该扩展，都会落到所有 tool 本来就会返回的同一条文本回退路径。app 发起的 tool call 仍要穿越宿主的同意闸门，才作为普通 tools/call 到达 server。",
  "mcpa-32-registry-flow": "验证过的 namespace 把 server.json 送进注册表，那里只有 aggregator 按自己的节奏读取。这与稍后某个请求能否到达后端无关：网关先对照请求 body 检查 Mcp-Method 与 Mcp-Name，匹配则路由到后端，不匹配则在进一步处理之前以 -32020 拒绝。SDK tier 徽章是第三个独立事实，被持续重新度量，而不是一次性授予。",
  "mcpa-33-capstone-flow": "一次事件响应交互同时触到所有领域：带缓存提示的 discovery、在请求同意之前就返回 isError 的 schema 检查、由 HMAC 签名 requestState 保护的 MRTR 往返、轮询到完成的 task，以及最终 result。同一个 trace id 串起每一跳，OAuth audience 校验把守唯一的 HTTP 调用，按哈希链连接的审计日志记录每一步的结果，并在最后仍然完成校验。",
  "mel-scale": "人耳对低频解得细、对高频解得粗。mel 尺度把线性 Hz 拗弯来匹配：1 kHz 以下近乎线性，以上急剧压缩——从 8 到 9 kHz 跨过的 mel 远少于 200 到 300 Hz。mel 滤波器组把分辨率花在耳朵真正在乎的地方。",
  "memory-blocks": "结构化 Agent 记忆把常驻上下文窗口的固定 core block，与磁盘上无界的 archival store 分开。Agent 读写自己的记忆：core 满了就总结，或把最不相关的条目逐出进 archival，需要时再把别的换页进来。Agent 就这样在有限窗口里装下实际上无限的历史。",
  "memory-consolidation": "最近的步骤以细致的 episodic 记录活着。缓冲越过阈值，最老的 episode 被压缩成保留大意、腾出窗口的紧凑 semantic 摘要。长期运行的 Agent 靠巩固活下来，而不是永远记住每个 token。",
  "metric-embedding": "retrieval 按 embedding 空间中的距离给候选排序。metric learning 塑造那个空间：triplet 或 contrastive loss 把同类点拉近、把其他类推开。簇一旦收紧，query 按余弦距离的最近邻就是可靠的正确答案。",
  "mfcc-pipeline": "MFCC 跑一条固定 pipeline：取 spectrogram，把它弯折到 mel 间隔的滤波器组上，取对数模拟响度感知，再做 DCT。DCT 把平滑的谱包络压进前几个系数——只保留最低的 12–13 个，就抓住了区分音素的声道形状，同时把音高和噪声留在更高系数里扔掉。",
  "mlp-forward": "两个输入穿过固定权重进入三个隐藏单元，各自被 tanh 压缩，再合成一个输出。蓝色边是正权重，金色是负权重；节点底色显示每个单元对你设定的输入反应多强。",
  "mlprod-drift-psi": "reference 窗口切成十个各占 10% 的桶。挪动当前窗口，各桶占比随之变化。PSI 把这些变化按对数比加权求和。一个桶从 10% 涨到 30%，贡献远大于涨到 12% 的桶。0.1 和 0.25 这两道线是信贷评分的经验法则，不是统计检验。",
  "mlprod-pit-join": "标签日在 day t 的训练行，只能用 day t 当天就存在的特征值。point-in-time join 取标签日当天或之前最新的一行，超过 TTL 就丢弃。按 user id 的朴素 join 取的是表里最新的行——那行常来自标签日之后，把未来抄进了训练集。",
  "mlprod-serving-cost": "batch scoring 每轮给每个用户都算一次分，成本随新鲜度上限缩短而增长。online serving 为峰值流量规模的副本付费，成本跟随请求数、与新鲜度无关。低于一小时，一小时一次的 batch 任务根本达不到时限。价格是为了练习取的整数。",
  "mm-action-tokens": "vision-language-action 模型要发出电机指令，但 transformer 只会说 token。RT-2 把每个归一化的关节目标离散成 256 个 bin 之一，再把 bin 映射成词表 id，于是 10 自由度的动作变成十个普通 token。同一个能给图像写说明的 decoder，现在也能写出控制轨迹——这就是 web 级知识能迁移到机器人身上的原因。",
  "mm-agent-loop": "computer-use Agent 循环运转：感知屏幕、围绕目标推理、发出结构化动作（点击坐标或键入字符串），然后观察输出的截图，再来一轮。每一轮就是一次多模态模型调用，难的是把动作 grounding 到正确的像素。错误会污染下一次观察，所以恢复能力与最初的计划同样重要。",
  "mm-doc-layout": "文档不是照片。标题、正文、图表、表格的含义都来自它们在页面上的位置。Donut、Nougat 这类 OCR-free 模型直接读页面图像、输出结构化标记；layout-aware encoder 则同时融合三路输入：文本内容、bounding-box 布局、图像 patch。「Total: $1,245」摆在哪儿，本身就是答案的一部分。",
  "mm-llava-projector": "LLaVA 用最简单的桥取代 Q-Former 瓶颈：一个两层 MLP，把每个冻结 ViT 的 patch embedding 从视觉维度映射到语言模型的 embedding 维度。每个 patch 变成 LLM 输入序列里的一个 token，直接在语言模型损失上训练。简单者胜。",
  "mm-maxsim": "Text-RAG 把整页压成一个向量，图表和表格就此丢失。ColPali 给每个图像 patch 保留一个向量、每个查询词保留一个向量，再用 MaxSim 打分：每个查询词在所有页面 patch 上取最大相似度，页面得分是这些最大值之和。关于图表的查询能直接咬住承载它的那个 patch，中间不需要 OCR。",
  "mm-mrope-axes": "Qwen2-VL 给每个 token 一个三分量位置，三个分量各绕自己的轴旋转：时间、高度、宽度。时间轴转得慢，一小时后的帧也落在不同的相位上；空间轴转得快，用来编码 patch 网格。一套不依赖绝对位置表的方案，同时覆盖单图、多图 batch 和长视频。",
  "mm-patch-n-pack": "每张图像保留原生宽高比，各自贡献自己的 patch 数：宽的图表、高的收据、小的图标各不相同。Patch-n-Pack 把它们全部接进同一条 transformer 序列，用块对角 mask 保证一张图只注意自己的 patch。不用缩放成正方形，也不浪费 padding token。",
  "mm-video-token-budget": "视觉 token 数随采样帧数增长，帧数随 FPS 乘时长增长。采样率翻倍，token 数翻倍，一小时的片子会冲垮任何固定的上下文窗口。三条出路：硬扛的百万 token 上下文、跨设备的 ring attention，以及激进的 pooling 或 Agent 式检索——绝不一次性加载整段视频。",
  "modality-projection": "分开的图像 encoder 和文本 encoder 各落在自己的空间里，匹配的一对起初指向不同方向。一个学到的投影把两者映进同一个 d 维共享空间，训练把匹配的向量转在一起，直到余弦逼近一。对齐之后，一个距离就能跨模态比较。",
  "model-cascade-router": "broker 给每个请求打分——任务类型、长度、置信度——把简单的多数派发给便宜模型。只有低置信请求沿虚线车道升级到 frontier 模型。大多数流量只花几分钱；同等质量下总账单降 20–60%。隐患是便宜模型的静默漂移——只有在线质量闸门能抓住。",
  "moe-routing": "router 把每个 token 送到 E 个 expert 里它的 top-k 个。每 token 只跑 k/E 的 expert block——尽管所有参数都驻留在内存里，活跃算力只是那个分数。路由不均会让少数 expert 过载，所以 MoE 训练要加 load-balancing 损失。",
  "monte-carlo-pi": "把点撒进单位正方形，数多少落进四分之一圆。这个比例就是面积比 pi/4，乘以四即 pi 的估计。样本越多估计越紧，但误差只按 1/√N 下降——这就是 Monte Carlo 的标志性代价。",
  "multi-agent-debate": "辩论里，几个 Agent 先各自独立作答，然后互读对方的记录、跨轮修订。分歧迫使每个人辩护或修正自己的推理，立场通常收敛向一个更好的共同答案。头一两轮就拿走了大部分准确率收益；再往后大家一致了，额外轮次主要在烧 token。",
  "multi-token-predict": "标准训练只监督每个隐藏状态预测唯一的一个下一 token——信号很弱。MTP 加了几个更深的头，各预测更远处的一个 token，链式连接以保住因果顺序。更丰富的信号磨利了主干，训练好的头在 inference 时还能兼任 speculative drafter。",
  "multihead-split": "multi-head attention 把模型维度切成等份，每头一份，所以头数必须整除 d_model。每头在自己的子空间里注意；切片再拼接回 d_model——加头不花额外的总宽度。",
  "multimodal-fusion": "图像 encoder 和文本 encoder 各自把输入映成向量。late fusion 把两者投影进共享 embedding 空间、只在最后比较——CLIP 这类对比模型就是这样对齐图像和 caption 的。early fusion 把两条 token 流拼接、从一开始就联合建模，两种模态全程互相注意。",
  "mx-gateway-fallback": "网关坐在你的应用与供应商之间，把路由、回退、重试、限速、密钥引用和可观测性收进一个 OpenAI 兼容 API。当主供应商返回 429 或 5xx，网关改道 fallback 供应商，请求依然完成。2026 年的格局：LiteLLM（MIT 协议、100+ 供应商、接近 2000 RPS 时崩）、Portkey（控制面、guardrails）、Kong AI（自家基准里最快）、Bifrost（自动重试）。数据驻留要求决定自托管还是托管。",
  "mx-priority-tiers": "2026 年的 Claude Constitution 把行为排成四层：安全与支持人类监督最高，伦理次之，Anthropic 准则第三，helpfulness 最后。层与层冲突时高层胜出——与 Unix 优先级或网络 QoS 同构。硬编码禁令凌驾于整个栈之上、不可覆盖；其余一切都在层级内按理由裁决，用可审计性换取对未见过情况的泛化。",
  "mx-propose-then-commit": "2026 年的 HITL 形态不是同步的 Approve 弹窗。被提议的动作先带着幂等键持久化，展示意图、影响半径和回滚计划，仅在明确确认后提交，然后再验证一遍确认副作用确实发生了。真正的失败模式是橡皮图章：看都不看就点 Approve。带明确清单的挑战—应答机制是有据可查的缓解手段。",
  "mx-research-loop": "AI Scientist v2 在没有人类模板的情况下闭合研究循环：生成想法、检查新颖性、在沙箱里起草并运行实验、让视觉语言模型点评图表、撰写论文，并在内部评审中迭代。一篇生成的论文通过了 ICLR 2025 workshop 评审。独立评估发现 42% 的实验死于代码错误、新颖性检查常把成熟方法误标为新方法——所以循环里决定可靠性的是沙箱这一侧的边缘。",
  "mx-schema-funnel": "LLM 返回字符串，你的应用需要类型化 JSON。在 prompt 里加一句「用 JSON 回答」大约九成时候有效，剩下一成直接崩溃。constrained decoding 在 token 层面补上这个缺口：有限状态机或文法对 logit 加掩码，任何会破坏 schema 的 token 在被采样之前就被禁止。输出从构造上就是合法 JSON，不靠后处理；Pydantic 层做类型校验，偶尔失手就重试。",
  "mx-sequential-test": "evals 回答「模型能不能干这活」；A/B 测试回答「用户在不在乎」。固定样本量测试惩罚偷看，所以 2026 年的平台用带始终有效边界的 sequential testing：边界早期宽、随时间收紧。累计统计量随机游走，越过边界就停止并上线；一直待在界内就判平。CUPED 降方差，Benjamini-Hochberg 校正同时测多个变体带来的多重比较。",
  "mx-speculative-tree": "EAGLE-3 在目标模型的隐藏状态上训练一个 draft head，其分布紧贴目标，通用聊天里接受率 alpha 落在 0.6 到 0.8 区间。draft 一次提出 K 个 token；目标模型用一次 forward 验证全部 K 个；被接受的 token 近乎免费。但每个被拒绝的 draft 都要再花一次目标模型 forward——所以当 alpha 低于约 0.55 且高并发时，这项技术是净亏损。先在真实流量上量 alpha，再拨开关。",
  "mx-tool-call-loop": "LLM 只会生成文本，所以它查不了天气也查不了数据库。function calling 是弥合差距的协议：模型输出结构化 JSON，点名要调用哪个函数、传什么参数；你的代码执行它；结果回灌进对话。模型是大脑，工具是双手，这个循环是神经系统。它不断重复，直到模型不再请求调用、给出最终答案——期间有并行调用与无限 tool loop 的防护。",
  "n5-block-stack": "结业项目把整个阶段叠进一个 decoder-only 模型：底部是 embedding，L 个重复 block 各含 causal attention 和一个 SwiGLU feed-forward，最后是 norm 加 LM head，逐字符采样莎士比亚。小到笔记本跑得动，正确到能继续放大。",
  "n5-chunk-cuts": "每一行的文档都相同，不同的只是下刀的位置。固定窗口便宜但会把句子拦腰斩断（标记的刀口）；recursive splitting 从段落边界退到句子再退到空格；semantic splitting 在相邻句相似度骤降处下刀。recursive 512-token 分块仍是基准默认。",
  "n5-crosslingual-bridge": "跨一百种语言预训练的单个 encoder，把同义的句子放进同一个共享空间里彼此相邻。在英文标签上微调一个任务头，再跨桥带过去：零乌尔都语标签也能给乌尔都语文本打分，几百条目标语言样本关掉剩下的大部分差距。",
  "n5-judge-gauge": "judge 模型读 query、检索到的 context 和答案，套一条 rubric，返回 0 到 1 的分数。RAGAS、DeepEval、G-Eval 全建立在这个循环上；要做的信任工作是冻结 judge 版本、并审计它偏袒长答案的偏差。",
  "n5-mel-decode": "Whisper 用眼睛听声音：波形变成 log-mel spectrogram，encoder 像 ViT 读 patch 那样读谱帧，decoder 一次一个 token 敲出转写，由选择语言和任务的特殊 token 引导。",
  "n5-patch-stream": "vision transformer 从不卷积：图像切成固定 patch，每个 patch 摊平、线性投影，排成一列 token 排在学出来的 [CLS] token 后面。position embedding 是对原始网格仅存的记忆；再往后就是标准的 transformer encoder。",
  "n5-slot-tracker": "三轮对话、对同一张 slot-value 词典的三次修改：先填 price 和 area，然后一次更正把 cheap 改成 moderate，接着 cuisine 到场。joint goal accuracy 只有每个 slot 全对才给这轮记分——对话中途的更正因此是追踪最难的部分。",
  "n5-subword-merge": "Byte-pair encoding 从字符出发，反复合并最高频的相邻对：先 (l,o) 和 (e,r)，再 (lo,w)，然后 (low,er)。高频词最终成为单个 token，生僻词拆成熟悉的碎片——任何输入都不会 out of vocabulary。",
  "naive-bayes": "每个类别在特征上有一条自己的钟形曲线。橙线是你观测到的值；圆点是每类产出它的可能性。Bayes 把这些 likelihood 按先验加权，变成后验长条——点属于 B 类的概率。",
  "ner-bio-tagging": "命名实体识别被表述成逐 token 打标签。BIO 方案给实体的第一个 token 标 B-TYPE，所有后续 token 标 I-TYPE，其余 token 标 O。序列标注器因此能表达多词实体和精确边界：「New York」是 B-LOC 接 I-LOC，区别于两个独立的单词地名。",
  "nerf-rays": "NeRF 把场景存成一个函数：给它一个 3D 点和视角方向，它返回密度和颜色。渲染一个像素时，从相机投出一条光线，沿它采样点，逐点查询 MLP，再从前往后按密度加权积分颜色。每条光线把空间中的一条线压成一个像素。",
  "ngram-backoff": "n-gram 模型用前 n−1 个词预测下一个词。n 调大，上下文更丰富，但可能的 gram 数量是词表的 n 次方，语料实际观测到的比例塌向零。大多数长上下文从未被见过——所以高阶模型必须对没见过的 gram 做平滑，退回到更短、更稠密的低阶 gram。",
  "nli-router": "NLI 拿一个前提 t 和一个假设 h，把这一对恰好路由到三个标签之一：entailment、neutral、contradiction。同一个分类器支撑着幻觉检查、grounded-QA 验证和 zero-shot 标注。",
  "noise-schedule": "alpha_bar 是第 t 步还存活的信号比例，它与剩余噪声之比就是信噪比。linear schedule 在前几步就把信号抹掉大半；cosine schedule 中段衰减得更平缓，让有用信号留得更久，给模型更有信息量的中间目标。",
  "norm-unit-balls": "norm 度量长度，它的单位球是所有长度为一的向量。L2 算平方和，给出圆；L1 算绝对值和，给出菱形；Linf 取最大坐标，给出正方形。选哪个 norm 改变了「什么算近」——正则化和距离因此都由它塑形。",
  "normalizing-flow": "normalizing flow 把一个简单的基础密度（灰色高斯）经可逆函数映射成复杂目标（蓝色）。因为映射可逆，换元公式给出精确密度：除以雅可比行列式的绝对值——对数域就是减去 log|det J|。映射拉伸空间处密度变稀，压缩处密度堆积——因为一切都是精确的，flow 可以用最大似然训练。",
  "nyquist-aliasing": "灰色是真实信号，蓝点是采样点，虚线是这些点暗示的波。只要采样率超过信号频率的两倍，采样点就能重建原波。把频率推过 Nyquist（fs/2），同样的点描出一条更低的假频率——这就是混叠，也是音频采样前先低通滤波的原因。",
  "object-detection-nms": "YOLO head 在每个网格单元都预测一个框，一个物体于是催生许多重叠候选（虚线）。Non-maximum suppression 按置信度排序，留下最强的，删掉与它重叠过多的每个框。活下来的是每个物体一个紧框。",
  "optimizer-trajectory": "损失面是一道窄峡谷：沿 x 平缓，沿 y 陡二十倍。朴素 SGD 在陡壁间来回弹跳、沿谷底缓慢爬行。Momentum 把弹跳抹平；Adam 对每个方向归一化，两个轴以相近的速度收敛。",
  "orchestration-pattern": "三种常见的多 Agent 拓扑，各自用韧性换控制。supervisor 把路由集中在 O(N) 条边上，却是单点故障。peer-to-peer 集群没有瓶颈，但付 O(N²) 的协调成本。hierarchy 透过层层 supervisor 分派，扇出可扩展，代价是每层加一截延迟。选哪个，取决于 Agent 之间必须说多少话。",
  "paged-kv-cache": "连续 KV cache 为每个请求预先保留完整的最大序列长度，大部分位置空着（灰色）。PagedAttention 把缓存放进按需分配的定长页：只有最后一页部分空闲（橙色）。内部浪费从「max − length」降到至多一页——同样的 GPU 上，分页缓存因此装得下多得多的并发序列。",
  "pass-at-k": "pass@k 问的是 k 个独立采样里是否至少一个解出任务。若每次尝试成功率是 p，全失败的概率是 (1−p)^k，pass@k 就是一减去它。再弱的模型，采样一多也陡峭攀升——所以 best-of-k 是这么便宜的杠杆，pass@1 和 pass@k 讲的是不同的故事。",
  "pca-axes": "PCA 找协方差矩阵的特征向量。蓝轴（PC1）指向散得最开的方向；橙轴（PC2）垂直于它，接住剩下的部分。特征值就是各轴上的方差，所以云越拉长、越相关，PC1 解释的方差就越大。",
  "perceptron-boundary": "perceptron 用 w·x + b 的符号做预测，所以决策面是一条直线。拖动权重和偏置，旋转并平移这条线，直到每个蓝色圆都在正侧、每个灰色方块都在负侧。",
  "perplexity-loss": "Perplexity 是 cross-entropy 损失的指数，读作模型每 token 在多少个等可能选项之间抉择。一个在大小 V 的词表上均匀乱猜的模型，perplexity 恰好是 V（橙线），所以任何有用的模型都必须远远落在这条线以下。",
  "pipeline-parallel": "模型被切成若干阶段，每张 GPU 一个，micro-batch 像流水线一样流过。流水线填充与排空时，部分阶段闲着——那个灰色气泡。气泡占比是（阶段数 − 1）除以（micro-batch 数 + 阶段数 − 1），所以喂更多 micro-batch 能把固定的填充排空成本摊到接近零。",
  "policy-gradient-landscape": "policy gradient 方法沿着能抬高期望 reward 的方向调整策略参数 theta。灰色曲线是 reward 地形，圆点是一步步爬向峰顶的上升轨迹。步长太小爬得慢；太大就冲过头；左边的小凸起若是起点，整段攀登会被困在那里。",
  "pooling": "pooling 把每个窗口概括成一个值来下采样特征图。2x2 窗口、步长 2，两个维度各减半，4x4 网格变成 2x2。max pooling 转发每个窗口里最强的 activation（高亮）；average pooling 转发均值。结果更小、对平移更宽容、对下一层更便宜。",
  "pos-tagger": "每个 token 拿到一个语法类别。tagger 从左到右扫过句子，给每个词贴上标签：determiner、noun、auxiliary、verb、adverb。lemmatizer 和 dependency parser 接下来读的就是这些标签。",
  "ppo-clip": "PPO 把 advantage 乘上新旧策略间的概率比 r。灰色是原始乘积 r·A；蓝色是裁剪后的替代目标。当比值沿「有帮助」的方向离开 1−eps 到 1+eps 的带域，clip 把目标函数削平、梯度归零——每次更新因此不会把策略推得离采数策略太远。",
  "precision-recall-threshold": "灰色是负类，蓝色是正类；橙线是阈值。右移它，正类预测变少：precision 升、recall 降。F1 是两者的调和平均，在两条曲线交叉处最高。",
  "prediction-game": "人逐个猜隐藏字母直到猜对；光靠猜测次数就能重建文本，所以猜测统计给出了每个字母的信息量上限。27 个符号的字母表理论上每字母可承载 4.75 bit；有上下文的人类猜手只需要接近 1。此后的每个语言模型都是这台游戏的机械玩家，perplexity 就是它的得分。",
  "prefill-decode-split": "Prefill 受算力限制；decode 受内存带宽限制。把两者塞进同一块 GPU，浪费的总是当前阶段用不上的那份资源。disaggregation 按各自瓶颈建两个独立池，KV cache 经高带宽 NIXL 链路跨池传送。长 prompt 才划算；短 prompt 付不起搬运成本。",
  "prompt-cache-hit": "跨调用重复的长 system prompt 或文档可以预填充一次、反复复用。缓存前缀（虚线）跳过重算，只处理新的后缀（实线）。省的钱等于命中率乘前缀占比：大而共享、且频繁命中的前缀，才是 caching 最划算的地方。",
  "qa-span": "抽取式 QA 从不发明答案。两个 head 分别预测给定段落中答案 span 的起止 token；模型扫过文本，点亮两者之间的连续区段。答案是逐字抬出来的——所以它没法幻觉。",
  "qlearning-gridworld": "Agent 学会抵达目标、避开深坑。格子底色是学到的 state value（蓝好琥珀坏），箭头是 greedy policy。早期数值都贴近零；随着训练，价值从目标向外传播，箭头排成一条绕开深坑的路径。",
  "quantization": "每个权重按它的位宽付存储费。位数减半，内存减半、吞吐约翻倍，而损失的精度随之增长。8-bit 几乎免费；4-bit 需要精细方案；再往下精度就守不住了。",
  "rag-chunking": "小块能精确定位相关段落，却把上下文打碎、让待索引的向量翻倍。大块保住上下文完整，却稀释每一次匹配、灌进 prompt 的 token 爆炸。overlap 软化边界，代价是更多的小块。",
  "rag-pipeline-flow": "数据包带着一个 query 走过装配好的 pipeline：rewrite 扩写它，hybrid index 检索，cross-encoder 重排，generator 带着 chunk 锚定的引用作答，置信度低就拒绝。六个孤立组件合成一个系统——整体胜过单独测量的任何一级。",
  "random-walk-diffusion": "一维随机游走每拍走 ±1 一步。各步独立、方差相加：t 步后方差是 t，离起点的典型距离是 √t。扩散得很慢——游走徘徊，却极少一路直奔远方。",
  "re-33-sweep-vs-descent": "蓝格是被方法解码成指令的字节。琥珀格是最后一个 retq 之后被当成代码解码的 padding 字节。灰格是无人认领的字节。实线框是方法找到的 basic block，虚线框是它还没找到的 block。箭头是方法已知的边，虚线箭头来自 .rodata 里的跳转表。",
  "re-36-prove-equal": "蓝格和蓝字节与原件一致。琥珀标记不一致的格或字节。虚线列是 relocation 字段——比较前两侧都清零。constants 行放的是 relocation 指向的五个表项。verdict 数格数、未掩码字节和表项。",
  "re-37-field-map": "蓝色标记和蓝列属于选中的工具。虚线按钮是本课没有运行的工具。evidence 行报告的是 code/main.py 里的 harness 对选中工具在课例 fixture 上测到的东西：ledger 在 -O1 下的 block 数、grade 在 -O0 下的跳转表、sweep-trap 里的数据字节，以及凭空发明、没有符号的函数。",
  "re-38-three-frames": "黑线是入口处的栈指针。在 x86-64 上，返回地址就贴在它上方。线上方的格属于调用方：栈参数，以及在 Microsoft x64 上的 32 字节 shadow space。线下方的格是被调方的帧：保存的寄存器、AArch64 上的帧记录、-O0 下溢出的参数寄存器；琥珀虚线框是函数用到时的 System V red zone。",
  "re-39-idioms-by-level": "蓝行是除法和除以 10 取模，琥珀行是 switch 的 lowering，绿行是向量化循环，紫行是无分支 select。不着色的行是序言、循环控制或识别器不认领的搬移。x86-64 在 -O0 下，除法已经是魔数乘法，取模是硬件 idivl，switch 是跳转表。arm64 在 -O0 下两者都用 sdiv，switch 是比较链。-O1 时两边的 switch 都变成查找表。-O2 和 -O3 时循环被向量化，x86-64 的 switch 又变回跳转表，arm64 的 switch 是比较树。",
  "re-40-call-through-three-formats": "实线框是已抵达的阶段，蓝框是当前阶段，虚线框是尚在前方的阶段。网格里蓝格表示方法找到或命名了那个函数起点，灰格表示错过，琥珀格则表示签名匹配到了错误的名字。",
  "re-41-struct-recovery": "蓝是整数成员或匹配的成员，琥珀是浮点成员或意见相左，黑是指针。灰色虚线连接线是一个没有任何访问触碰过的 DWARF 成员。折叠按钮只作用于 -O2 构建——那里向量化循环一遍读八个元素：不开折叠，报告会说结构体末尾之外还有七个字段。",
  "re-42-run-timeline": "圆是函数入口断点，菱形是分支后继上的断点，方块是 a->balance 上的硬件 watchpoint。对钩是在该停点被证实的断言，叉是被驳倒的断言，问号是整个运行从未观测到的断言。-O2 构建一路跑到退出、完全不停——它的裁决全部来自退出那一列。",
  "re-43-five-containers": "实心蓝方格是容器存下的信息，空心方格是它丢掉的。蓝行是控制流指令：原生代码和 CIL 里的跳转加一张表，CPython 里的比较-跳转对，JVM 里的 tableswitch，WebAssembly 里的嵌套块和 br_table。琥珀行在指令本身内嵌变量名——只有 CPython 的清单这么做。",
  "re-44-matches-and-paths": "实线蓝线是逐字节精确匹配，琥珀线是掩掉 relocation 字段后才匹配的，虚线是助记符或流图形状的匹配，点线是仅凭符号名的匹配。虚线框是当前视图里没有匹配的函数。树里 q 是 score / 10 − 6，r 是返回值；每个叶子都汇入共享的返回块 0xa1。",
  "re-45-scorecard": "蓝格通过。琥珀格失败，evidence 会点名第一个不一致的格、字节数、未解决的引用或对不上的摘要。虚线琥珀格是部分通过：类型全一致、至少一个名字不同，并标出字符错误率。两个候选全字段通过。一个候选编译回原始字节、通过每个输入，却仍失败——因为它的报告引用了对象里不存在的 helper、地址和字符串。",
  "re-evidence-ledger": "蓝色实线：通过或一条观测到的记录。蓝色虚线：推导得出。琥珀虚线：未知——只有一部分运行。琥珀实线：一条悬空的链接。灰色：无支撑或未决。verdict 数的是它上方的那些行。",
  "react-trace": "ReAct 把推理与行动交错。每个 Thought 决定做什么，每个 Action 调一个工具，每个 Observation 把结果喂回来。把推理显式写出来，Agent 才能从走错的一步回头，而不是将错就错。",
  "receptive-field": "CNN 深处的神经元看不见整幅图，只看得见透过下面每一层喂给它的 patch。每个 kernel 把那个 patch 加宽 (kernel − 1)，任何 stride 把后续所有层的触达乘大。叠小 kernel 是网络廉价攒出大感受野的方式——不需要一个巨型滤波器。",
  "reflection-loop": "自我改进循环：行动、评估结果、批评哪里出了错、在下一次尝试前修订。每一轮都抬高质量，但收益几何式缩水、很快走平。功力在于知道反思什么时候开始不回本。",
  "relation-triples": "关系抽取先把实体 span 锚进文本，再把它们连成带类型的边。「Tim Cook」和「Apple」成为节点，动词短语成为两者之间带标签的边。三元组聚合起来，就是知识图谱。",
  "rerank-funnel": "便宜的 retriever 返回 N 个候选；cross-encoder 带着完整注意力逐个读（query, document）对并打分。只有 top-K 存活（蓝）。贵的模型只跑 N 次而不是全语料次，精度提升正好落在请求延迟预算之内。",
  "reward-model": "奖励模型把人类偏好变成一个标量分数。对每对人标注的「chosen 优于 rejected」，Bradley-Terry 目标训练模型让 chosen 的得分更高。分数差距越大，模型认为人类偏好 chosen 的概率越高，偏好损失越小。",
  "rewoo-plan": "ReWOO 把推理和观察分开。planner 一遍写完整条工具调用链，worker 依序执行、步骤之间不再调模型。ReAct 则在每个动作前都调一次模型、重读整条不断变长的轨迹——跑得越久 token 花得越多。",
  "rlhf-reward-kl": "RLHF 最大化 reward 减去一项把 policy 拉近 reference 模型的 KL 惩罚。β 太小，惩罚咬不住，policy 就追着代理 reward 漂移、钻奖励模型的空子。KL 项就是拴住 reward hacking 的那条绳子。",
  "rmsnorm-vs-layernorm": "灰色是原始特征向量，蓝色是归一化输出。LayerNorm 先减均值再除标准差，把每个向量重新居中到零。RMSNorm 完全跳过均值，只除均方根——更便宜，还保留任何常数平移。加一个平移，看 LayerNorm 把它吸收掉，而 RMSNorm 放它通过。",
  "rnn-unroll": "循环网络是同一个 cell 应用在每个时间步、权重共享。沿时间展开它成了一条链：每个 cell 用 tanh 把新输入折进上一个隐藏状态，再把结果传给下一步。最终状态见过整个序列——这也正是长序列难把 gradient 传回去的原因。",
  "rnn-vs-parallel": "RNN 拖着一个隐藏状态逐步走过序列，1000 个 token 的输入就是 1000 个串行步骤。transformer 让每个位置在一次并行矩阵乘法里注意所有位置。就是「丢掉循环」这一个决定，让曲线在 2017 年之后继续扩张。",
  "roofline": "算术强度是 kernel 每移动一个字节做了多少 FLOPs。左侧斜屋顶表示性能被内存带宽封顶；右侧平屋顶表示被原始算力封顶。屋脊是两者交汇处。落在屋脊左下方的 kernel（橙色）是 memory-bound，解法是提高数据复用，不是换更快的芯片。",
  "roots-of-unity": "n 次单位根是 z^n = 1 的 n 个复数解。它们以 2πk/n 的角度均匀围在单位圆上，其中总有一个在 1。这些等距点正是离散 Fourier 变换背后的采样频率。",
  "rope-explorer": "RoPE 把每一对维度旋转一个随位置增大的角度。低维用高频（转得快，编码近处顺序）；高维用低频（转得慢，编码长程距离）。调大 base 会拉长每一个波长、扩展可用上下文。",
  "rrf-fusion": "一个 query 同时跑 BM25 和稠密 retriever。各返回一份排序列表；RRF 用 1/(k+rank) 跨列表求和给每份文档打分，任何一路排得好的文档都会上浮。融合靠投票而不是插值——所以它在各种 query 类型上都赢。",
  "rvq-codec-cascade": "神经音频 codec 不用一个巨型 codebook，而是级联多个小 codebook：第一个量化 encoder 输出，后面每个量化剩下的残差。递减的长条就是残差沿栈变小。强令 codebook 0 承载语言内容（semantic）、其余承载声学细节——token 化语音模型由此成立。",
  "s0-cell-order": "方括号里的数字记录的是 cell 何时运行，不是它排在哪。重跑 cell 2 会把 [2] 变成 [4]，但 cell 3 仍持有旧顺序的结果——磁盘上那个文件永远显示不出的隐藏状态。当计数不再自上而下递增，Restart and Run All 是唯一诚实的检查。",
  "s0-commit-dag": "每个 commit 指向它的父提交，所以历史是一张图，不是一份列表。分支只是提交的分叉路径：main 继续前进，实验在自己的线上生长，merge commit 把两个父提交接在一起。正因如此，你可以在完全不碰 main 的情况下试验一个危险的改动。",
  "s0-data-pipeline": "原始 CSV 从不被原地修改：它流进一个带类型、被压缩的 Parquet 工件，再流进用固定种子切出的 train、val、test 三份。因为每支箭头都是脚本、种子被钉死，任何人都能重新生成你的指标所计算的那几行精确数据——实验因此可比。",
  "s0-env-isolation": "两个 pin 都正确，只是不能共用一个解释器。全局安装时，第二个 pip install 会覆盖第一个，两个项目一起坏。每个项目一个 virtual environment，各自的 site-packages 互不相通——torch 2.4 和 torch 2.1 就在同一台机器上共存而永不相见。",
  "s0-env-stack": "环境自底向上搭建：先是 OS 和 GPU 驱动，然后包管理器，然后语言运行时，最后是依赖这三者的 AI 库。当 import torch 失败时，沿着栈向下走——出问题的那层几乎从来不是抛错的那层。",
  "s0-flame-hot": "你怀疑的 GPU 计算并不是瓶颈；profiler 显示这一步大部分墙钟时间耗在 DataLoader 里。每根条是调用内的累计时间、堆叠在调用者之上，所以最宽的那座塔标出该修的函数——这里是给 loader 加 worker 和 pinned memory，而不是优化模型。",
  "s0-gpu-dispatch": "GPU 赢在矩阵乘法是数千个独立的乘加运算——恰是它核心并行化的对象。同样的 batch 在 CPU 上一次漏过一个块，在 GPU 上却是流式涌过——所以在 CPU 上跑 8 小时的训练，在 T4 上只要约 10 分钟。先确认车道存在：nvidia-smi，然后 torch.cuda.is_available()。",
  "s0-image-layers": "Dockerfile 的每条指令加一层只读层：CUDA base、Python、torch，你的代码在最上面。完成的镜像就是冻结的整个栈，所以 docker run 在你的笔记本和租来的 GPU 机器上产出同一个容器——works-on-my-machine 这个失败模式随之消失。",
  "s0-list-vs-generator": "两个循环读同样的八行。list 版本在第一个训练步开始前就把所有行读进内存。generator 版本只握着一个两行的 batch，batch 备好第一步就开跑。换成真实数据集：list 需要装下整个文件的内存，generator 只需要装下一个 batch。",
  "s0-lsp-roundtrip": "编辑器不懂 Python；语言服务器才懂。每次编辑都把一条 didChange 通知发上线，服务器重新检查文件，诊断结果回来画成波浪线和悬浮提示。装上 Python 与 Pylance 扩展，这个循环在每次击键时运转；不装，编辑器就只是个文本框。",
  "s0-process-fork": "在 Linux GPU 机器上一切都是从父进程 fork 出来的进程：init 生出 sshd，你的登录生出 bash，bash 生出训练任务。Ctrl-C 的 SIGINT，或对 ps aux 里找到的 pid 执行 kill，会终结叶子进程、释放它的 GPU 显存——这就是你收回一台被死任务占着的机器的方法。",
  "s0-secret-inject": "被提交的代码只写变量名；值住在被 gitignore 的 .env 文件里，运行时注入进程环境，再作为 Authorization header 发出。一旦密钥出现在源码里，它就随仓库的每一次 clone 一起出走，而泄露的密钥记在你的账单上。",
  "s0-shell-pipeline": "管道把一个命令的 stdout 交给下一个命令的 stdin，中间没有临时文件。日志流整条进入，grep 丢掉每一行不含「loss」的行，awk 只留第 8 列——训练输出的消防水管变成一串干净的数字，可以实时盯着看或画出来。",
  "sae-features": "稀疏自编码器把一个稠密 activation 分解成一个大得多的特征集，其中大多数保持关闭。特征 activation 上的 L1 惩罚决定编码有多稀疏。太弱，特征保持稠密、多义；太强，少数特征包办一切、重建受损。甜点位给出少数活跃、单一语义的特征——每个都对应一个人类可读的概念。",
  "safety-checkpoints": "一个请求穿过三个 checkpoint。pre-gen 阶段检测器可以直接拦下；during-gen 阶段 token 过滤器见到违禁词就掐断流；post-gen 阶段分类器和规则引擎检查完整输出。闸门汇总各裁决、执行最终动作，并画出一条每个审查者都读得懂的审计轨迹。",
  "sampling-decoder": "解码按顺序跑三道过滤器。temperature 重塑分布，top-k 封顶候选数量，top-p 保住覆盖概率 p 的最小集合。幸存者重新归一化后从中采样。",
  "sandbox-runner": "生成的代码经 stdin 送进子进程里一个全新解释器，配 import denylist 和输出上限。每条提供的断言跑一遍，点亮 pass（蓝）或 fail（橙）；wall-clock 超时杀掉失控循环。得分是断言通过的比例——崩溃和超时都是一等公民的失败模式。",
  "scalable-oversight": "弱裁判无法直接检查强 Agent 在困难任务上的表现：灰色曲线随难度上升跌向随机。监督协议帮裁判跟上。辩论式：两个强 Agent 对抗，裁判选更有理可依的一方；递归式：任务被分解成裁判能验证的碎片。无论哪种，蓝色曲线都衰减得更慢——裁判在它独自永远解不了的任务上仍高于随机。",
  "scaling-laws": "Chinchilla 拟合从参数量和 token 数预测损失。在固定算力预算下，损失在每参数约 20 token 附近最低。大多数早期大模型严重训练不足：参数太多，token 太少。",
  "score-matching": "score-based 模型学的是 score——log 密度的梯度——画出来就是指向数据稠密处的灰色向量场。生成不需要显式密度：从噪声出发，沿 score 反复走步（Langevin 动力学，每步加一点噪声）。橙色样本跟着箭头走出空旷区，落进一个高密度模式——diffusion 模型采样正是这么画的。",
  "segmentation-flood": "分割是逐像素的分类。encoder 压缩图像以提供上下文，decoder 上采样回全分辨率，skip connection 把精细的空间细节带过去、边界保持锋利。看每个像素认领自己的类别、mask 向外漫延。",
  "self-critique-loop": "不必花钱请人打偏好标签，模型给自己评分。它起草一份回答，对照成文的原则 constitution 批评这份草稿，然后改写。修订后的对子成为训练信号——对齐工作的大头就这样在模型内部循环完成。",
  "self-refine": "Self-Refine 让同一个模型写答案、批评自己的作品、再修改，把输出循环回输入。头几轮抓明显的毛病、涨得最多；后面几轮越来越没得改，质量爬向天花板然后走平。功力在于知道额外几轮什么时候开始不配它们的 token。",
  "semantic-cache": "semantic cache 在新 query 的 embedding 与缓存条目足够接近时，直接用存好的答案回复。每个圆点是一条进来的 query，按它与最近缓存条目的余弦相似度摆放；橙线右侧的阴影区从缓存出答案。阈值调高，命中变少但几乎不出错；调低，缓存更多但可能端出过期或不对题的旧答案（橙点）。",
  "semantic-cache-hit": "L1 semantic cache 给每条 prompt 算 embedding、与历史条目比相似度。近似重复的 query（蓝）直接从缓存出——快且几乎免费。只有真正新颖的 prompt（橙）miss 到底层的冷 LLM。命中率从开放聊天的 10% 到结构化 FAQ 的 70%；前缀里的动态文本一多就塌到近零。",
  "sentiment-logits": "线性文本分类器给每个词记一个学到的权重，连同偏置求和成一个 logit，再过 sigmoid 压成概率。正权重推向正面情感，负权重反向拉扯。决策在概率一半处翻转——求和的 logit 正好在零上穿过。",
  "seq2seq-alignment": "attention 给 decoder 一层对源文本的软对齐。每个目标 token 读的是所有 encoder 状态的加权和，权重沿源行 softmax 归一。这里「maison」注意「house」、「rouge」注意「red」，偏离对角线的格子暴露出翻译需要的重排。权重尖锐则锁定一个源词，扁平则混合几个。",
  "skill-approval-decision": "决策树把本地可逆动作路由到沙箱执行，越界动作送人工批准，被拒的批准即停止。",
  "skill-argument-boundaries": "用户文本依次变成解析后的参数、skill 上下文、带类型的工具调用、经验证的执行输入。",
  "skill-authoring-loop": "对 workflow：观察、立契约、打包、评估、按失败层分类、修复，闸门通过才发布。",
  "skill-authority-chain": "被激活的 skill 影响模型的提案；提案必须过能力、权限、批准、隔离、验证五关。",
  "skill-disclosure-levels": "三层堆叠分别展示 catalog 元数据、激活的 SKILL.md 正文、分支专属资源。",
  "skill-discovery-pipeline": "配置好的 root 依次经过 enumeration、package validation、provenance、冲突消解、预算分配，最后发布 catalog。",
  "skill-eval-layers": "六层评估喂给同一个发布闸门：结构、路由、行为、脚本、安全、可移植性。",
  "skill-host-adapter": "可移植的 skill bundle 和 host adapter 各自向同一个运行时激活边界贡献不同输入。",
  "skill-invocation-stages": "单个 skill_used 标志会藏住失败发生的边界——是路由、policy、能力还是验证出的错。",
  "skill-package-anatomy": "包完整性覆盖 workflow 点名的每一个文件。发布 catalog 条目之前先验证整棵树。",
  "skill-package-install": "源 skill bundle 依次变成 manifest、完整的安装树、经验证的包、被发现的 catalog 条目、eval 冒烟测试。",
  "skill-reference-map": "直接的决策地图胜过话题倾倒。每个辅助文件都该写明加载条件。",
  "skill-resource-containment": "决策树拒绝绝对路径、父目录穿越、symlink 逃逸、错误文件类型和超大资源。",
  "skill-routing-abstention": "请求先过 actor 资格检查和描述比对，然后才能在 activate、ask、abstain 之间做出明确决定。",
  "skill-runtime-lifecycle": "按生命周期阶段诊断失败。discovered、selected、activated、executed、verified 是不同的状态。",
  "skill-tool-orthogonality": "一个反馈循环：被激活的 skill 引导流程，host 工具返回观察，最终产出 artifact。",
  "skill-trust-surface": "包指令、引用、任务内容、脚本、host 工具、文件、网络、凭据、外部效应——合成一张威胁面。",
  "skill-validation-order": "便宜的结构检查应当先失败，否则二级内容错误会把第一个被破坏的不变量藏起来。",
  "skill-workflow-extraction": "任务依次经过模型分类、分支引用、确定性证据收集、模型解读、artifact 契约和验证。",
  "sliding-window-attention": "行是 query，列是 key。蓝格是 token 真正注意到的配对；灰格在因果三角形内、却被窗口切掉；白色是未来，永远被掩。全因果注意力填满整个下三角，代价 O(N²)。宽度 w 的滑动窗口只保留带状对角线，降到 O(N·w)——长上下文因此养得起。",
  "softmax-attention-scaling": "点积随 head 维度增长，不缩放的话分数变大、softmax 饱和到一个 token 上，梯度被杀死。除以 d_k 的平方根抵消这种增长，注意力分布在任何维度上都保持校准。",
  "softmax-temperature": "温度在指数之前先除 logits。低于 1 时分布向头部 token 收尖；高于 1 时向均匀摊平。T→0 时是 argmax；T→∞ 时是抛硬币。",
  "sp-asr-attention": "Whisper 是 encoder-decoder 结构。encoder 把 30 秒的 log-mel 窗口变成一排音频帧，decoder 一次发一个 token，每一步都对那些帧做 cross-attention。高亮的条带显示：随着转写推进，注意力从左向右漂移——这是学出来的软对齐，而不是 CTC 模型那种固定的逐帧标签。",
  "sp-codec-tokens": "神经音频 codec 用残差向量量化把声音离散化：第一个 codebook 抓住信号本体，后面每个 codebook 各自量化剩下的残差。把第一个 codebook 拆成语义部分（语言内容，金色）与声学残差，transformer 就能像预测词语那样预测语音 token。decoder 把每帧选中的码字逐帧求和，还原成波形。",
  "sp-eer-crossover": "调高阈值，更多真人被拒之门外（false reject rate 上升）；调低阈值，更多冒名者混进来（false accept rate 上升）。橙色线扫过阈值区间，停在两条曲线的交点。这个交叉点就是 Equal Error Rate——说话人验证榜单上人人都要报的那个数字。",
  "sp-fullduplex": "pipeline 式的 voice agent 有延迟下限，因为每一段都要等上一段。full-duplex 模型把 pipeline 压扁：它一边吃进用户的音频流，一边同时吐出自己的音频流，文本 inner monologue 只是中间产物而非必经阶段。听与说重叠——200 ms 的响应延迟就是这么来的。",
  "sp-tts-stack": "现代 text-to-speech 分三段。frontend 把字符串变成 token，acoustic model 一列一列画出 mel spectrogram，vocoder 把 mel 变成可听的波形。端到端 flow-matching 模型把后两段糅在一起，但推理和调试一个合成语音时，这三段图景依然是你的思考框架。",
  "sp-vad-cascade": "检测器给每 20 ms 的帧打上语音或静音标签。句中短暂的停顿不能结束对话轮次，所以静音要持续撑满 hangover 计时器，端点检测才会触发。hangover 设太短，你会打断用户；设太长，助手永远在等。只有持续静音超过计时器，这一轮才算结束。",
  "sp-voice-factorize": "语音克隆与转换都建立在一个分解上：把「说了什么」和「谁在说」分开。源音频被分解成 content representation 和 speaker embedding；丢掉源说话人，换上从 B 的五秒录音里取出的 reference embedding。内容与新说话人重新组合，得到 B 说出同样的话——这正是同意门禁和水印必须强制存在的原因。",
  "sp-wer-align": "Word error rate 本质是编辑距离。识别结果与参考文本逐词对齐，每个错位记作 substitution、deletion 或 insertion。三者之和除以参考词数就是 WER。这里五个参考词里有一次 substitution（kitchen 错成 chicken）、一次 deletion（the）、一次 insertion（now），共得 60%。",
  "spectrogram-window": "spectrogram 把信号切成窗、对每窗做 Fourier 变换。短窗钉死「什么时候发生」，能量却摊到频率上；长窗把音高解得细，却沿时间抹开。两种分辨率的乘积固定——每个选择都是在拿一个换另一个。",
  "speculative-decoding": "小的 draft 模型便宜地提出 γ 个 token；大的目标模型一次并行前向全部验证，接受最长的正确前缀，然后自己再吐一个 token。一致率越高，接受的连续段越长，每轮取代的目标模型调用越多。",
  "summarize-collapse": "抽取式摘要给每句打分、按顺序抬出最核心的几句，长文档塌缩成几行原文。生成式摘要则改写：读起来流畅，但可能捏造源文本从未说过的内容。",
  "supervisor-hierarchy": "supervisor 把任务拆给 worker Agent，worker 自己还可以再 supervise。Agent 总数是分支因子沿深度的几何和——很小的扇出也会让人数迅速爆炸。树要浅。",
  "svd-rank-reconstruction": "保留最大的 k 个奇异值，就得到矩阵的最优 rank-k 近似。头几个奇异值抓住大部分能量，低秩即可几乎精确重建模式，而存储的数字少得多。压缩和 low-rank adapter 的全部思想就在这里。",
  "svm-margin": "support vector machine 不只是分开两类，它把边界推到离两边都尽可能远。虚线标出 margin；贴着虚线、金色描圈的点是 support vector。移动其他任何点，什么都不会变。",
  "sw-agent-card-discovery": "A2A 是 Agent 之间的横向线协议。客户端先从 well-known URL 取一张 Agent Card，弄清远端 Agent 会什么，再发一条消息——远端 Agent 把它变成任务。任务走一段不透明生命周期（TASK_STATE_SUBMITTED、TASK_STATE_WORKING、TASK_STATE_COMPLETED），返回 artifact。它就是 HTTP 加 REST，把 Agent 重新表述成一等公民的对等端。",
  "sw-checkpoint-replay": "持久化执行是多 Agent 系统扩展出单台笔记本的关键。运行时每步之后按线程 id 写一个 checkpoint。worker 中途崩溃时租约释放，另一个 worker 接起任务、从最后一个已提交的 checkpoint 续跑，而不是从头再来。",
  "sw-contract-net": "FIPA contract-net 协议把任务分配变成密封拍卖。manager 广播征集提案，空闲 Agent 回以报价，manager 把合同判给最优报价。MCP 的 tools/call 和现代任务市场，都是这个 1980 年代机制的 JSON 版重述。",
  "sw-ctde": "Centralized Training, Decentralized Execution 是合作式 MARL 的脊梁。训练时 critic 看得见每个 Agent 的状态和动作，治好了困扰独立学习者的非平稳性。测试时 critic 退场，每个 actor 只凭自己的局部观测运行。MADDPG、QMIX、MAPPO 是同一拆分的三种演绎。",
  "sw-debate-topology": "聚合 N 个 Agent 不是简单多数决，接线方式很重要。star 全部经过枢纽，chain 传递接力棒，tree 分叉，graph 让所有人互辩。MultiAgentBench 发现 graph 最适合研究型任务，代价是超过约四个 Agent 后协调税开始爬升。",
  "sw-handoff-routing": "OpenAI Swarm 把编排压缩成两个原语：routine（prompt 加工具）和 handoff（一个返回下一个 Agent 的工具）。没有状态机。模型靠调用正确的 handoff 来路由，此刻握着对话的 Agent 就是当家的。",
  "sw-theory-of-mind": "真正的协调需要 Agent 彼此建模。高阶 theory of mind 是推理「一个 Agent 认为第三个 Agent 相信什么」。Riedl 2025 发现：只有在 theory-of-mind prompt 下，这才产生真正面向目标的分化；撤掉 prompt，表面上的协调在统计控制下不复存在。",
  "sw-work-stealing": "集群没有中央调度器。任务落在共享队列上，空闲 worker 自己拉走下一件。协调活在队列语义里，系统扩展到队列扩展为止。代价是确定性：你用一份连贯的全局计划换来了吞吐。",
  "swarm-auction": "Agent 为任务竞价，报价随轮次上涨。出价最高者（a1）赢得任务，却只付第二高的价——虚线。在第二价格机制下，诚实报价是占优策略——机制设计因此偏爱用它给 Agent 之间分配工作和 token。",
  "swarm-blackboard": "Agent 通过中央黑板共享事实，而不是复制消息。危险是记忆投毒：一个 Agent 写进一段幻觉，下游每个读者都把它当作已验证采纳，准确率无声下滑。撑得住的缓解是来源记录、不可写的 verifier、以及每 Agent 独立视图。",
  "swarm-consensus-wave": "决策沿环涟漪般扩散，诚实的 Agent 收敛到共享值。单个拜占庭节点（X）拒绝翻转，朴素多数决仍可能被俘获。经典 BFT 容忍 f < n/3 个这种节点；对 LLM Agent 来说，开放问题是相关故障，不是任意故障。",
  "swarm-hierarchy-token": "manager 拆分目标，经 sub-manager 层层委派给 worker；结果沿同样的边返回。风险在于：LLM manager 每轮都要重新推理整棵树，context 的一点漂移就会错配工作、结构陷入循环。很多时候，一条扁平序列反而更强。",
  "swarm-message-bus": "Agent 不再互传原始字符串，而是在共享总线上讲带类型的协议。MCP 载工具调用，A2A 载委派任务（和回复），ANP 载身份。分开车道，多 Agent 系统才可审计，不同团队造的 Agent 才能互操作。",
  "swarm-messages": "如果每个 Agent 都跟其他每个 Agent 说话，消息数按 N·(N−1) 增长，朴素 broadcast 是平方级扩展。所有流量改经 supervisor 中转，边数降为线性——大型系统因此都把协调集中起来。",
  "swarm-roles": "Agent 更多没用，Agent 不同才有用。计划、工件、主观批评、确定性检查是各自带工具的独立角色。verifier 是承重墙：MAST 把几乎每一起多 Agent 失败都追溯到缺失或损坏的验证。一个 reject 就把工件送回去重新计划。",
  "swarm-speaker": "Agent 对一个共享池做反应，而不是对固定图。一个选择器——轮转、LLM 或自定义规则——挑出下一个发言者，token 在候选间跳转、最终落定一个。这避免了在 N 个 Agent 之间硬编码每种交接的边爆炸。",
  "swarm-stigmergy": "没有哪个 Agent 在规划路线。每个 Agent 走过时留下信息素、偏爱更浓的痕迹，最短路因此积聚流量、绕路蒸发。ACO 把这一套变成 Agent 路由：痕迹记录哪个 Agent 处理过哪种任务类型，衰减让更好的路线可以被重新发现。",
  "swiglu-ffn": "普通 FFN 把输入过一个矩阵加 ReLU：零点处一道硬折角。SwiGLU 从同一输入分成两路——值路 x·W 与门路 swish(x·V)——再相乘。门按坐标平滑地把值放大或缩小，给网络一个柔软、可学习的开关；现代开源模型用它取代了平平无奇的 ReLU。",
  "t3-capstone-chain": "每个无状态 MCP 请求都携带 version 与 capabilities。网关做认证并施加策略；server 可以返回官方 task 扩展句柄，client 用 tasks/get 轮询；独立工作经 A2A SendMessage 委派。最终的 ui:// 报告与每个边界 span 保持关联，不依赖任何协议会话。",
  "t3-dispatch-loop": "server 从 stdin 每次读一行 JSON 对象。带 id 的消息是 request，必须在 stdout 上恰好产生一条携带同一 id 的 response。notification 没有 id，也不产生任何输出。任何打到 stdout 上的其他东西都会污染线路——这就是 debug 输出走 stderr 的原因。",
  "t3-gateway-funnel": "对每个开发者来说，网关看起来就是一个 MCP server。内部：每次调用先认证，再对照每用户 RBAC 检查、限速、与固定的 tool-hash manifest 比对、写入审计日志，然后才路由到拥有该 tool 的后端。策略住在同一个地方，而不是五千份 IDE 配置里。",
  "t3-jwks-rotate": "授权服务器按计划把签名密钥从 kid A 滚动到 kid B。启动时只取过一次 JWKS 的资源服务器从那一刻起拒绝所有 token。生产形态是：缓存密钥集 + 刷新任务在旧密钥过期前覆盖缓存 + 缓存未命中时的回退拉取——新密钥签发的 token 在凌晨 3 点也能通过验证，无需重启。",
  "t3-primitive-sort": "不是所有东西都是 tool。模型应该按查询决定是否调用它——那是 tool。用户把它作为上下文附加——那是 resource。可复用单元是整个工作流——那是 prompt。按这个方式整理一个笔记 server，能消掉纯读取场景的模型往返，让每项能力落在宿主本来就为它构建好的 UX 界面上。",
  "t3-roots-boundary": "把被授权的目录或资源 URI 作为显式 tool 参数、资源引用或 server 配置传入。server 在访问之前解析并约束每一条路径：内部读取成功，外部路径被拒绝。MCP Roots 仅在其废弃窗口内可用，且绝不替代授权或 OS 沙箱。",
  "t3-sampling-flip": "对新的 MCP 设计而言 sampling 已废弃；直接调用模型供应商即可。兼容性 server 在当前协议下不会发出反向 request：它返回 resultType 为 input_required 的 sampling inputRequest，client 在自己的策略下取得补全，然后带着 inputResponses 和逐字节相同的 requestState 重试原方法。",
  "t3-scope-stepup": "scope 为 notes:read 的 token 撞上一个需要 notes:write 的动作。server 不让调用失败，也不重跑整套 OAuth 流程，而是以 403 应答，并用 WWW-Authenticate header 点名缺失的 scope。client 请用户只为这一增量授权，然后带着升级后的 token 重试。最小权限保持默认，因为升权的代价这么低。",
  "t3-skill-layers": "AGENTS.md 告诉任何 Agent 这个项目如何运作。SKILL.md 把一个工作流打包成 frontmatter 加正文，运行时渐进披露。MCP 提供 skill 调用的 tools。因为每一层都是开放格式的普通文件，同一套 bundle 直接落进 Claude Code、Cursor 和 Codex，而不是复制三份各自漂移。",
  "t3-span-waterfall": "一个 trace id 覆盖整轮。agent span 最先打开、最后关闭；它内部，一次 LLM 调用、一次 tool 执行和被包裹的 MCP dispatch 各自拥有带 gen_ai 属性的 span。当后端冷启动，被拉长的正是 mcp.call 那根条——而这恰恰是光靠日志回答不了的问题。",
  "t3-ui-sandbox": "tool 结果指名一个 ui:// 资源，宿主把它的 HTML 渲染在沙箱化 iframe 里。iframe 拿到锁死的 CSP，除非元数据明确授予否则没有网络——进出沙箱墙的唯一通道是一套极小的 postMessage JSON-RPC 方言。同一份 HTML bundle 在所有兼容 client 里渲染一致。",
  "task-decomposition": "长程 Agent 不正面硬啃复杂目标。它把目标分解成子任务，子任务再分解，直到叶子都是能直接执行的步骤。分支更宽、树更深，计划得更彻底，但要追踪的工作量成倍涨——所以有用的计划保持浅。",
  "tensor-broadcast": "broadcasting 让不同形状的数组无需复制数据就能组合。把形状从右端对齐；每对维度要么相等，要么有一个是 1、被拉伸。其他任何冲突都是错误。bias 向量之所以能干净地加到整个 batch 上，靠的就是它。",
  "tensor-parallel": "把权重矩阵按列切块，一次大矩阵乘法就被拆到多张 GPU 上。每张 GPU 用自己的切片乘完整输入、产出部分输出，再由 all-gather 把切片缝成完整结果。每张 GPU 的参数量按卡数下降——一层大到单卡装不下的模型就是这样被服务的。",
  "throughput-latency": "蓝色是吞吐量，灰色虚线是单请求延迟。更大的 batch 让 GPU 更忙，每秒总 token 数爬升；但每个请求在别人后面等得更久，延迟也上升。拐点（橙色）是吞吐几乎不再增长、而延迟持续爬升的地方——大多数 serving 系统瞄准的 batch size 就在这里。",
  "tokenizer-tradeoff": "更大的词表把文本切成更少的 token，序列更短、注意力更便宜。但 embedding 表和输出表随词表变大，收益又用参数还回去。真实的 tokenizer 落在两种压力的平衡处，大约 32K 到 128K。",
  "tool-routing": "router 拿 query 和每个已注册的工具描述打分、选最接近的。function 名字和描述不是装饰：它们正是 router 决定调用哪个工具所用的信号。",
  "topic-drift": "无监督主题建模不需要标签。散乱的词汇按共现或 embedding 相似度聚成几组连贯的簇；每个簇读它的头部词，就念出语料「在谈什么」的潜在主题。",
  "tp-client-merge": "真实的 host 同时加载多个 MCP server，把各自发现的工具列表摊平成模型看到的一个命名空间。client 对每个 server 调 server/discover，给名字加前缀避免冲突，并记住每个工具属于哪个 server——调用才能路由回正确的进程。",
  "tp-parallel-fanout": "单轮模型可以同时发出几个独立的工具调用。host 并发执行，总延迟从所有调用之和塌缩到最慢单个的时长。这里三个天气查询各有各的时钟，但这一轮只等最长的那个。",
  "tp-router-failover": "routing gateway 在多个 provider 之上给一个统一 API 表面。最高优先级的 provider 出错时，请求沿 fallback 链重试直到有人应答——不用重新部署。同一层还按请求追踪成本和 token，让每个工作负载落在「够用中最便宜」的模型上。",
  "tp-schema-routing": "选择是一个匹配问题。模型读每个工具的名字和描述，把 query 路由到最贴合的。含糊或互相重叠的描述让光束游移、选错；锋利的「何时用 X、何时不该用」措辞把它锁死在一个工具上，准确率抬升十到二十个点。",
  "tp-task-lifecycle": "官方 tasks 扩展让长时间运行的工作返回一个 task 句柄，而不是把请求一直挂着。client 用 tasks/get 轮询；终态的 task 自带最终结果。task 进入 input_required 时，tasks/update 提供对未决 inputRequests 的响应，tasks/cancel 表达取消意图。当前扩展没有 tasks/list 或 tasks/result 方法。",
  "tp-tool-loop": "每套 tool calling 栈都跑同一个四步循环。host 描述工具，模型决定调哪个，host 真实执行，模型在下轮之前观察结果。数据包绕圈，是因为循环重复到模型不再需要调用为止。",
  "tp-tool-poisoning": "工具描述是 prompt 的一部分。恶意 server 可以埋一句用户永远看不到的指令，让模型去读一个秘密、悄悄泄漏出去。接口看起来完全正常——所以防御是给描述做 hash pinning、在 CI 里扫描 injection 模式，而不是信任。",
  "tp-transport-handshake": "两种传输、两种部署形态。stdio 用 stdin 和 stdout、配一个本地子进程。MCP 2026-07-28 Streamable HTTP 是无状态的：每条 JSON-RPC 消息各自 POST 到同一个端点，该请求返回 JSON 或 request 范围的 SSE。没有 Mcp-Session-Id、独立 GET 流，也没有会话 DELETE。",
  "trace-spans": "分布式 trace 是铺在时间轴上的 span 树。root span 盖住整个请求；LLM 调用、retrieval、工具调用各自的 child span 按起始时间和时长嵌在里面。读 gantt 图就知道延迟到底去了哪儿——这是每起生产事故的第一个问题。",
  "transfer-learning": "预训练 backbone 已经认识通用特征——边缘、纹理、形状。迁移学习冻结这些低层，只训练顶部几层加一个新 head 来适配目标任务。可训练参数更少，意味着要存的梯度更少、要拟合的数据远更少、收敛更快；数据集很小时多冻几层，数据集又大又不同时少冻几层。",
  "transformer-residual": "transformer block 有两个子层：self-attention，再一个 feed-forward network，各自包着 add-and-norm。虚线是残差旁路——把输入 x 原样带过去，在子层之后加回来。几百个 block 能叠起来而梯度不在半路死掉，靠的就是这些旁路。",
  "tree-of-thoughts": "Tree of Thoughts 把单条链变成搜索。每一步模型提出几个候选想法；打分器排序，beam 只留最好的几个继续展开。剪掉弱枝让指数级的树变得养得起，同时 Agent 还能从坏的一条推理线回头。",
  "v4-3d-multiview": "2026 年的 text-to-3D 栈把问题一分为二。多视图 diffusion 模型（Zero123、MVDream、SV3D）从一张照片或一句 prompt 生成一圈一致视角；重建步骤再用梯度下降把一团带朝向的 3D Gaussian 拟合到这些视角上。渲染 splat 只是投影加 alpha 合成——所以结果能在消费级 GPU 上跑到实时帧率。",
  "v4-alm-tokens": "音频语言模型保留三件套模板：音频编码器（Whisper、BEATs）把每段声音变成 embedding，projector 把它们映射进 LLM token 空间，decoder 让它们与文本 prompt 内联同读。回答「有人受伤吗」需要同时读到三个事件：那声犬吠、那声喊叫、喊叫之后的寂静。这个联合读取恰恰是纯转写 ASR pipeline 扔掉的东西。",
  "v4-audio-watermark": "AudioSeal 风格的水印给生成语音的每个样本加一个学习得到的、不可感知的信号。重点不是保密而是存活：经过 MP3 压缩、裁剪和重采样，检测器仍能恢复把这段音频标记为合成的载荷比特。AASIST、RawNet2 这类检测模型对付不配合的对手；水印管你自己的输出。语音克隆要两个一起上。",
  "v4-controlnet-zero": "ControlNet 克隆预训练 U-Net 的编码器半边，给克隆喂一张姿态图，再通过初始化为零的 1x1 卷积把它的特征接回冻结的 decoder。第 0 步时旁路恰好是无操作，训练只可能比底模更好；随着 zero-conv 暖起来，姿态开始驾驭生成。LoRA 在权重本身上玩同一个把戏：冻结注意力矩阵旁边的一条低秩增量。",
  "v4-video-temporal": "2D+pooling 模型对每帧跑同一个图像 CNN、再沿时间平均特征，于是「向左推」和「向右推」坍缩成同一个 clip 向量。3D 卷积的核在时间和空间上同时滑动：它一次看到一小段帧窗口，能编码方向。时空 transformer 把这个想法推到底——对所有 (t, h, w) token 联合做注意力，代价是随 clip 长度平方增长。",
  "v4-vision-pipeline": "生产视觉服务是一条契约链：解码字节、检测边框、裁剪每个框、对裁剪分类，最后组装一份结构化响应。每支箭头都是一个可能无声失败的接口（坐标顺序、归一化、缩放插值），所以输出在离开服务前要过一道 Pydantic schema。检测器或分类器随便换；骨架不动。",
  "v4-vlm-projector": "每个生产 VLM 都是同样三件套。ViT 把图像切成 patch 并编码；一个小 MLP 把这些 patch embedding 投进 LLM 的 token 空间；decoder 把图像 token 与文本 token 当作一条交错序列来读——「有几辆红车？」由普通的 next-token prediction 回答。模式就位后，换 ViT、换 projector、换 LLM 都是机械操作。",
  "v4-voice-latency": "800 ms 的体感来自重叠，不来自任何一个特别快的组件。STT 在半句话上就开始，LLM 在部分转写上就开始，TTS 在前几个 token 出来后就开始——第一字节目标约 750 ms 落地，卡在预算之内。用户插话时，VAD 事件立刻取消 TTS 和播放：pipeline 里最快的路径就是叫停它的那条。",
  "v4-world-rollout": "纯视频生成从 prompt 预测帧然后停止。world model 是同一个视频 DiT 在循环里跑：每段去噪完的 chunk 被追加进上下文，一个动作 token（左转、开门）条件化下一段预测，模型就变成一个可以驾驶的学习型仿真器。漂移是它的失败模式——每个被幻造出来的像素都会成为未来的输入。",
  "vae-latent-grid": "VAE 把输入映进一个平滑的 latent 空间，再把空间中的点解码回输出。左边的方块是这个空间的一片切片，圆点是你的 latent code。挪动它，右边的解码形状随之连续形变——因为 decoder 训练成相邻的编码产出相邻的输出。",
  "value-iteration-gamma": "value iteration 把 reward 从目标一格一格向回推。这条链上唯一的 reward 在最右格，所以每个状态的价值就是 gamma 的「到目标距离」次方。gamma 太小，远处的 reward 几乎一文不值（短视）；gamma 接近 1，价值能沿链条一路传回。",
  "vector-projection": "蓝色是 a，灰色是 b 的方向，橙色是 a 投在 b 上的影子。标量投影 |a|cos θ 在两向量垂直时缩为零，角度越过 90° 后变为负。虚线是从 a 落到 b 上垂足的那条垂线。",
  "video-diffusion-denoise": "3D VAE 把片段压成时空 patch，diffusion transformer 对它们去噪。灰色斑点是模型一步步除掉的噪声；蓝色形状跨帧浮现并移动——那是网络必须建模的时间连贯性：同一个物体、光照和运动贯穿整条带。",
  "video-temporal-patches": "视频同时在空间和时间上 token 化。每个 224 像素的帧切成空间 patch 网格，帧沿时间组成 tubelet。token 总数是时间份数乘空间份数，注意力成本又随 token 数平方增长——长片配细 patch 就爆预算。更大的 patch 和 tubelet 是压住预算的主要杠杆。",
  "voice-pipeline": "voice agent 是一条以帧为单位的 pipeline，不是文本外挂 TTS：voice activity detection、speech-to-text、LLM、text-to-speech，全部压在严酷的 ~600ms 预算里。partial 音频是默认，barge-in 取消逆流而上——每一段都必须流式，而不是等完整一轮。",
  "voyager-skills": "终身 Agent 把每个解过的任务变成一个命名的、可复用的 skill 存起来。episode 越攒越多，库越长越大；后面的任务靠组合架上已有的 skill 更快解决，而不是从零开始。能力复利：每次成功都让下一个问题更便宜。",
  "vq-codebook": "VQ-VAE 的 encoder 产出连续向量（蓝点），但模型需要离散 token。每个向量吸附到最近的 codebook 条目（橙方块），图像变成一串整数编码。codebook 更大，量化更细、重建误差更低——但每 token 花更多 bit，还冒着永远用不上的编码的风险。",
  "wb-ab-runs": "同一个任务在同一仓库上跑两遍：一次只靠 prompt，一次走完整工作台。五个被测量的结果替你争论：测试、范围、反馈记录、交接质量与回退次数。两条泳道里模型完全相同，面板是唯一变量，统计结果就是你递给怀疑者的论据。",
  "wb-builder-marker": "builder 不能给自己的工作打分，所以它的工件穿过墙上的一个槽口，进入另一个 loop——不同的 system prompt、不同的目标、只读权限。评审者逐行对照 rubric 打分并产出报告；它做的任何事都改不了 builder 产出的东西。",
  "wb-feedback-loop": "每条命令都经过 runner，它把 stdout、stderr、exit code 和时长捕获成结构化记录。第一次运行以 exit 1 失败，被路由进下一轮的是那份记录，而不是 Agent 对输出的想象；重试随后在同一条证据链上挣到 exit 0——闸门读的正是这条链。",
  "wb-gate-sequence": "闸门是对 Agent 已产出的工件的确定性函数：规则报告、范围报告、反馈记录和 diff。这次变更通过了规则、范围与反馈，但验收没有任何运行过的记录，所以最终闸门保持放下，done 保持 false——无论聊天里怎么说。",
  "wb-handoff-packet": "会话结束时，工作台把状态、结论与评审压缩成一个交接包，抛过边界。旧会话变暗，新会话点亮时已经知道自己的第一个动作——下一个 Agent 在第一分钟就进入产出，而不是花三十分钟重新发现前三十秒。",
  "wb-init-probes": "一个确定性脚本在 Agent 做任何事之前探测运行时、依赖、路径与测试命令，把每个答案写进 init 报告。只有每盏灯都亮起，闸门才抬起、真正的工作才开始；冷启动的会话直接读报告，不必再交一次发现税。",
  "wb-pack-install": "结业项目把十一课的面板压缩进一个带版本的目录：路由、schema、脚本、模板和一个安装器。每个文件落到目标仓库的对应槽位；第二次运行检测到已存在就跳过——这个包因此可以永远安全地重复应用。",
  "wb-rule-checkoff": "散文式指令只会说「小心」；约束会说哪条检查失败了。规则检查器把规则集逐条对照运行工件，把每条规则标记为通过或失败，违规于是成为报告里具名的一行，而不是一种感觉。规则可 diff，评审因此能精确看到哪条约束变了。",
  "wb-runtime-shapes": "基于队列的后台工作、事件驱动触发器和定时 cron 任务，是六种生产运行形态中的三种。每种入口都把工作交给同一个 Agent loop，但形态决定哪些失败可挽回：队列可以重试，事件可以重放，cron 必须假设上一次运行已经死掉。",
  "wb-runtime-spawn": "Agno 推荐的生产形态：无状态的会话域后端——每个请求在微秒级实例化一个全新 Agent，会话状态存在 store 里，响应之后 Agent 即被销毁。Mastra 在 TypeScript 里押同样的注：带类型的 Agent、Tool 与 Workflow，架在标准 server 适配器后面。",
  "wb-scope-bounce": "契约列明任务可以写到哪里、绝不能写到哪里。落在允许 glob 内的 diff 通过；朝禁用路径漂移的 diff 撞上契约边界被弹回，变成一条具名违规和一份回滚计划——由检查器抓住，而不是两天后由评审者抓住。",
  "wb-seven-surfaces": "一个前沿模型单独工作时只是闪烁：代码看似合理，却没有完成定义，也不记录它假设了什么。可靠性出现在七个工作台面板依次停靠到位时：指令、状态、范围、反馈、验证、评审与交接。拆掉任何一块，对应的失败模式就会回来。",
  "wb-state-persist": "会话结束，聊天气泡就消散；状态文件不会。每次写入先过 schema 检查再落地，revision 原子递增，下一个会话、下一个 Agent 和评审者读到的都是同一个带版本的文件，而不是各自重新推导工作停在哪里。",
  "wb-three-files": "最小可用工作台：一份 Agent 首先读取的简短根路由，一份行动前读、行动后写的状态文件，以及一块写明什么在途、什么被阻塞、接下来是什么的任务板。读打开每一轮，写关闭每一轮，循环的任何一环都不依赖聊天记录存活。",
  "wb-trace-ingest": "OTel GenAI 之上的平台层：摄入 span、渲染 trace 瀑布图、对单个步骤跑评估。Langfuse 还配了 prompt 管理与会话回放；Phoenix 偏 RAG 评估与自动埋点；Opik 偏 prompt 优化与 LLM 裁判的幻觉检查。",
  "weight-init-variance": "每层把 activation 方差乘上 n·Var(w) 的增益。天真的大权重让增益随宽度增长，activation 爆炸（对数轴）。Xavier 取 Var(w)=1/n，He 对 ReLU 取 2/n，都把增益按在 1 附近，信号幅度于是不随深度衰减。",
  "weight-tying": "输入 embedding 把每个 token id 映射成一个 d 维向量；输出投影把隐藏向量映射回词表上每个词条的 logit。两者都是 vocab×d 矩阵、扮演互逆的角色，所以很多模型把它们绑在一起：输出层复用转置后的 embedding。整整一块 vocab×d_model 的参数被省掉——词表上万 token 时这是笔大钱。",
  "word-vector-arithmetic": "Word2Vec 把词摆成「关系即方向」的样子。man 到 king 的向量与 woman 到 queen 的向量相同，所以从 king 减去 man、加上 woman，几乎正好落在 queen 上。语义成了几何，类比成了向量加法。",
  "workflow-chain": "最简单的 workflow：一条固定的线性模型调用链，上一个输出是下一个输入，步骤之间可插程序化的闸门。图由工程师全权所有，调试便宜、运行可预测。只有步骤无法预知时，才伸手去拿 Agent。",
  "world-model-rollout": "基于模型的规划在触碰世界之前先模拟未来。从当前状态出发，Agent 想象每个候选动作会到的状态，用学到的模型把它们向前推演，然后才落子最好的一步。rollout 越深计划越好，想象之树却指数生长。",
  "zero-sharding": "朴素数据并行在每个 GPU 上复制完整的优化器状态、梯度和参数。ZeRO 分阶段消灭冗余：stage 1 切分沉重的 Adam 优化器状态，stage 2 加上梯度，stage 3 连参数本身也切。每升一级，单卡内存再降一截——用一点通信换取训练大得多的模型的能力。"
};
